// A recipe's views (docs/KNOWLEDGE-BASE.md, step 9): its ingredients both ways (R2), metric and imperial (R3) and its
// mise-en-place (R5), every one computed from the compiled record and the reader's address, never stored. Unit conversion is
// arithmetic on the record's own amounts; volume becomes weight only for an ingredient whose recipe states `grams_per_cup`
// (DECIDE 7), never from a table of densities. Pure, so the page, the sheet and a test read the same numbers.

import { formatNumber, formatQuantity } from "./marks.mjs";

/** The unit systems a reader can ask for; absent is the recipe's own units. */
export const UNIT_SYSTEMS = Object.freeze({ metric: "Metric", imperial: "Imperial (US)" });

/** @typedef {keyof typeof UNIT_SYSTEMS} UnitSystem */
/** @typedef {{ amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }} Quantity */

/** The system an address asks for (`?units=metric`), or null for the recipe's own. @param {string | null} value @returns {UnitSystem | null} */
export function readUnits(value) {
  return value === "metric" || value === "imperial" ? value : null;
}

/** Grams in one of each mass unit. */
const GRAMS = /** @type {Record<string, number>} */ ({ g: 1, kg: 1000, oz: 28.349523125, lb: 453.59237 });
/** Millilitres in one of each volume unit (US customary). */
const MILLILITRES = /** @type {Record<string, number>} */ ({ ml: 1, l: 1000, tsp: 4.92892159375, tbsp: 14.78676478125, "fl oz": 29.5735295625, cup: 236.5882365 });
/** The spoons a cook uses in either system, kept as written. */
const SPOONS = new Set(["tsp", "tbsp"]);

/** A unit's one spelling: "teaspoons" is tsp, "Cups" is cup. @param {string} unit */
function canonical(unit) {
  const u = unit.trim().toLowerCase().replace(/\.$/, "");
  const aliases = /** @type {Record<string, string>} */ ({
    gram: "g", grams: "g", kilogram: "kg", kilograms: "kg", ounce: "oz", ounces: "oz", pound: "lb", pounds: "lb", lbs: "lb",
    millilitre: "ml", millilitres: "ml", milliliter: "ml", milliliters: "ml", litre: "l", litres: "l", liter: "l", liters: "l", // codespell:ignore (British input accepted)
    teaspoon: "tsp", teaspoons: "tsp", tablespoon: "tbsp", tablespoons: "tbsp", cups: "cup", "fluid ounce": "fl oz", "fluid ounces": "fl oz",
  });
  return aliases[u] ?? u;
}

/** A number rounded as a cook reads it in a unit: whole grams, quarter cups, half ounces. @param {number} n @param {string} unit */
function round(n, unit) {
  const step = unit === "cup" ? 0.25 : unit === "lb" ? 0.1 : unit === "oz" ? 0.25 : unit === "tsp" || unit === "tbsp" ? 0.25 : n < 10 ? 0.1 : 1;
  return Math.round(n / step) * step;
}

/**
 * One amount in a unit of `system`: grams become ounces and the reverse, millilitres become cups and the reverse, spoons stay. In
 * metric, a volume of an ingredient with `gramsPerCup` becomes its weight. A unit neither system knows (a pinch, 2 eggs) is
 * left as written, and so is an amount with no number.
 *
 * @param {number} value
 * @param {string} unit
 * @param {UnitSystem} system
 * @param {number | null} gramsPerCup
 * @returns {{ value: number, unit: string } | null}
 */
function convert(value, unit, system, gramsPerCup) {
  const u = canonical(unit);
  if (u in GRAMS) {
    const g = value * /** @type {number} */ (GRAMS[u]);
    if (system === "metric") return g >= 1000 ? { value: g / 1000, unit: "kg" } : { value: g, unit: "g" };
    const oz = g / /** @type {number} */ (GRAMS.oz);
    return oz >= 16 ? { value: oz / 16, unit: "lb" } : { value: oz, unit: "oz" };
  }
  if (u in MILLILITRES) {
    if (SPOONS.has(u)) return null;
    const ml = value * /** @type {number} */ (MILLILITRES[u]);
    if (system === "metric") {
      if (gramsPerCup) return { value: (ml / /** @type {number} */ (MILLILITRES.cup)) * gramsPerCup, unit: "g" };
      return ml >= 1000 ? { value: ml / 1000, unit: "l" } : { value: ml, unit: "ml" };
    }
    if (ml < 15) return { value: ml / /** @type {number} */ (MILLILITRES.tsp), unit: "tsp" };
    if (ml < 60) return { value: ml / /** @type {number} */ (MILLILITRES.tbsp), unit: "tbsp" };
    return { value: ml / /** @type {number} */ (MILLILITRES.cup), unit: "cup" };
  }
  return null;
}

/**
 * An amount as the reader asked for it: scaled by `factor` (a fixed amount is not), then in `system` when one is asked for.
 *
 * @param {Quantity} q
 * @param {number} factor
 * @param {UnitSystem | null} system
 * @param {number | null} [gramsPerCup]
 */
export function showQuantity(q, factor, system, gramsPerCup = null) {
  if (!system || q.min === null) return formatQuantity({ ...q, raw: "" }, factor);
  const scale = q.fixed ? 1 : factor;
  const low = convert(q.min * scale, q.unit, system, gramsPerCup);
  if (!low) return formatQuantity({ ...q, raw: "" }, factor);
  const high = q.max !== null && q.max !== q.min ? convert(q.max * scale, q.unit, system, gramsPerCup) : null;
  // A range is shown in the unit of its low end, so "1 to 2 cups" never reads "1 cup to 0.5 quart".
  const highValue = high ? (high.unit === low.unit ? high.value : (q.max ?? 0) * scale * (low.value / (q.min * scale))) : null;
  const amount = highValue !== null ? `${formatNumber(round(low.value, low.unit))} to ${formatNumber(round(highValue, low.unit))}` : formatNumber(round(low.value, low.unit));
  return `${amount} ${low.unit}`;
}

/** A temperature in the other scale, to the nearest 5 degrees as an oven dial reads. @param {number} t @param {"C" | "F"} to */
const toScale = (t, to) => Math.round((to === "F" ? (t * 9) / 5 + 32 : ((t - 32) * 5) / 9) / 5) * 5;

/**
 * A step's words with its temperatures in the asked-for system's scale: "180 °C" reads "355 °F" in imperial, and the reverse in
 * metric. HTML in, HTML out: only the text of a temperature changes.
 *
 * @param {string} html
 * @param {UnitSystem | null} system
 */
export function showTemperatures(html, system) {
  if (!system) return html;
  const from = system === "imperial" ? "C" : "F";
  const to = system === "imperial" ? "F" : "C";
  return html.replace(new RegExp(`(-?\\d+(?:\\.\\d+)?)(?:\\s*(?:to|-)\\s*(-?\\d+(?:\\.\\d+)?))?\\s*°${from}`, "g"), (_all, low, high) =>
    high !== undefined ? `${toScale(Number(low), to)} to ${toScale(Number(high), to)} °${to}` : `${toScale(Number(low), to)} °${to}`,
  );
}

/** The anchor of a step on the page: its list's scope and its number. @param {string} scope @param {number} number */
export const stepId = (scope, number) => `${scope}step-${number}`;

/**
 * Every step each ingredient is used in, in the page's order: the other half of R2, read from the marks the compile already
 * put on each step. Keyed by the ingredient's name, lower-cased, as the record's materials are.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function ingredientSteps(record) {
  /** @type {Map<string, Array<{ number: number, id: string }>>} */
  const uses = new Map();
  for (const section of record.sections) {
    section.blocks.forEach((block, i) => {
      if (block.type !== "steps") return;
      for (const step of block.steps) {
        for (const m of step.materials) {
          const key = m.name.toLowerCase();
          const list = uses.get(key) ?? [];
          if (!list.some((u) => u.number === step.number && u.id === stepId(`${section.id}-${i}-`, step.number))) {
            list.push({ number: step.number, id: stepId(`${section.id}-${i}-`, step.number) });
          }
          uses.set(key, list);
        }
      }
    });
  }
  return uses;
}

/**
 * The grams in a cup of each ingredient whose recipe states it, by lower-cased name.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function gramsPerCup(record) {
  return new Map(record.materials.flatMap((m) => (typeof m.gramsPerCup === "number" ? [[m.name.toLowerCase(), m.gramsPerCup]] : [])));
}

/**
 * A step's ingredients, each with its amount as the reader asked for it: the first half of R2.
 *
 * @param {import("./render.mjs").ProcedureRecord["sections"][number]["blocks"][number] extends infer B ? B extends { type: "steps", steps: Array<infer S> } ? S : never : never} step
 * @param {number} factor
 * @param {UnitSystem | null} system
 * @param {Map<string, number>} densities
 * @param {Map<string, string>} [names] the ingredient list's words for each ingredient, which the step's own marks may shorten
 */
export function stepIngredients(step, factor, system, densities, names = new Map()) {
  return step.materials.map((m) => {
    const q = step.quantities.find((x) => x.name?.toLowerCase() === m.name.toLowerCase());
    return { name: names.get(m.name.toLowerCase()) ?? m.display, amount: q ? showQuantity(q, factor, system, densities.get(m.name.toLowerCase()) ?? null) : null };
  });
}

/** Each ingredient's words in the ingredient list, by lower-cased name. @param {import("./render.mjs").ProcedureRecord} record */
export function ingredientNames(record) {
  return new Map(record.materials.map((m) => [m.name.toLowerCase(), m.display]));
}

/**
 * The mise-en-place: every ingredient once, with its total amount at the reader's servings and units, in the order of the
 * ingredient list; and the same as plain lines, a shopping list to copy (R5).
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 * @param {number} factor
 * @param {UnitSystem | null} system
 */
export function miseEnPlace(record, factor, system) {
  const items = record.materials.map((m) => {
    const amount = m.amount ? m.amount : m.quantity ? showQuantity(m.quantity, factor, system, m.gramsPerCup ?? null) : null;
    return { name: m.display, amount };
  });
  return { items, text: items.map((i) => `- ${i.amount ? `${i.amount} ` : ""}${i.name}`).join("\n") };
}

app/kb/registry/compile.mjs.source:
// The one door from a registry file to the row the registry is drawn from (docs/REGISTRY.md): parse, validate, hash.
// build:content, sync:content, the gates and the adapter's registry save all call compileRegistryItem, so a file CI
// passes is the file the save accepts. Pure and dependency-light, so the Worker and the Node scripts import the same
// module.
//
// An item is ONE file, `content/registry/<kind>/<id>.md`, and the file is its front matter and nothing else. What
// every kind has (a name, and `draft` for its status) is the table's own columns; what a kind knows beyond that is its `fields`
// (app/kb/registry/kinds.mjs), judged by that kind's rules. The validator REFUSES any field the kind does not
// declare, so nothing enters the repository or D1 that a page would not show, and it states a value nobody has yet
// as "MISSING: <why>", never a guess.

import matter from "gray-matter";

import { gitBlobSha } from "../../lib/content/hashes.mjs";
import { foldText } from "../../lib/cv/view.mjs";
import { KINDS, kindKeys } from "./kinds.mjs";

export const REGISTRY_DIR = "content/registry";

/** An id within a kind: lower-case letters, digits and hyphens, so it is a file name and a URL segment as written. */
export const ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
/** A kind is a key of KINDS: the same shape, so it is a directory and a URL segment as written. */
const KIND_PATTERN = /^[a-z][a-z-]{0,30}$/;
const NAME_MAX = 120;

const GAP = /^MISSING:\s*(\S.*)$/s;

/** True for a recorded gap: `MISSING: <why>`. @param {unknown} value @returns {value is string} */
export function isGap(value) {
  return typeof value === "string" && GAP.test(value);
}

/** The registry address of an item, `<kind>/<id>`: what the drift check, the sync and Carrel read it by. */
export function registrySlug(/** @type {string} */ kind, /** @type {string} */ id) {
  return `${kind}/${id}`;
}

/**
 * The kind and id a slug names, or null when it is not exactly `<kind>/<id>` in the allowed shapes, so a slug can
 * never name another path.
 *
 * @param {string} slug
 * @returns {{ kind: string, id: string } | null}
 */
export function parseRegistrySlug(slug) {
  const parts = slug.split("/");
  if (parts.length !== 2) return null;
  const [kind = "", id = ""] = parts;
  return KIND_PATTERN.test(kind) && ID_PATTERN.test(id) ? { kind, id } : null;
}

/** The repository path of an item's file, from its slug. */
export function registryPath(/** @type {string} */ slug) {
  return `${REGISTRY_DIR}/${slug}.md`;
}

/**
 * @typedef {import("./kinds.mjs").KindSpec} KindSpec
 * @typedef {import("./kinds.mjs").RegistryItem} RegistryItem
 * @typedef {import("./kinds.mjs").RegistryHost} RegistryHost
 * `findWideDashes` is injected, as the page compile injects the pipeline's: the Worker loads it lazily.
 * @typedef {{ findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> }} RegistryPipeline
 */

/**
 * Judges one file and, when it passes, builds the item. Every message the file has is returned, never the first
 * alone, so a writer fixes all of them at once.
 *
 * @param {{ slug: string, raw: string, host: RegistryHost, pipeline: RegistryPipeline, kinds?: Readonly<Record<string, KindSpec>>, sourcePath?: string }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], item: RegistryItem, record: string, gaps: Array<{ field: string, reason: string }>, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compileRegistryItem({ slug, raw, host, pipeline, kinds = KINDS, sourcePath }) {
  /** @type {string[]} */
  const errors = pipeline
    .findWideDashes(raw)
    .map((hit) => `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`);

  const address = parseRegistrySlug(slug);
  if (!address) {
    return { ok: false, errors: [...errors, `"${slug}" is not a registry address; it is <kind>/<id>, such as ${kindKeys(kinds)[0] ?? "primer"}/m13-forward (lower-case letters, digits and hyphens)`] };
  }
  const { kind, id } = address;
  const spec = kinds[kind];
  if (!spec) {
    return { ok: false, errors: [...errors, `"${kind}" is not a registry kind; the kinds are ${kindKeys(kinds).join(", ") || "none yet"}`] };
  }
  if (!raw.startsWith("---")) errors.push("the file must start with a --- front matter block");

  let parsed;
  try {
    // An options object, even an empty one: gray-matter caches by input when it is omitted.
    parsed = matter(raw, {});
  } catch (error) {
    return { ok: false, errors: [...errors, `the front matter is not valid YAML: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`] };
  }
  const data = /** @type {Record<string, unknown>} */ (parsed.data);
  if (parsed.content.trim() !== "") errors.push(`the body must be empty: a ${spec.singular} is its front matter and nothing else`);

  const allowed = ["name", "draft", ...Object.keys(spec.fields)];
  for (const key of Object.keys(data)) {
    if (!allowed.includes(key)) errors.push(`${key} is not a ${spec.singular} field; a ${spec.singular} carries ${allowed.join(", ")} and nothing else`);
  }

  const { name, draft } = data;
  if (typeof name !== "string" || name.trim() === "" || name !== name.trim() || /[\r\n]/.test(name) || name.length > NAME_MAX) {
    errors.push(`name is ${JSON.stringify(name)}; it is the ${spec.singular}'s name on one line, at most ${NAME_MAX} characters`);
  }
  if (draft !== undefined && typeof draft !== "boolean") {
    errors.push(`draft is ${JSON.stringify(draft)}; it is true or false, or absent for a published item`);
  }

  /** @type {Record<string, unknown>} */
  const fields = {};
  /** @type {Array<{ field: string, reason: string }>} */
  const gaps = [];
  for (const [field, fieldSpec] of Object.entries(spec.fields)) {
    const value = data[field];
    if (value === undefined || value === null) {
      if (fieldSpec.required) errors.push(`${field} is required for a ${spec.singular}; write the value, or "MISSING: <why>" if nobody has it yet`);
      fields[field] = null;
      continue;
    }
    if (typeof value === "string" && /^MISSING\b/.test(value) && !isGap(value)) {
      errors.push(`${field} is ${JSON.stringify(value)}; write MISSING: and the reason it is missing`);
      continue;
    }
    if (isGap(value)) {
      gaps.push({ field, reason: value.replace(/^MISSING:\s*/, "") });
      fields[field] = value;
      continue;
    }
    const message = await fieldSpec.check(value, { host, data });
    if (message) errors.push(`${field}: ${message}`);
    fields[field] = value;
  }
  if (errors.length > 0) return { ok: false, errors };

  /** @type {RegistryItem} */
  const item = {
    kind,
    id,
    name: /** @type {string} */ (name),
    status: draft === true ? "draft" : "published",
    fields,
  };
  return {
    ok: true,
    errors: [],
    item,
    // Only what the shared columns do not hold: a name is stored once, in its column.
    record: JSON.stringify(fields),
    gaps,
    sourcePath: sourcePath ?? registryPath(slug),
    sourceBlobSha: await gitBlobSha(raw),
  };
}

/**
 * What only the whole set can say: two items of a kind cannot share a name (folded, so case and accents do not make
 * two), and a kind's own rules about its set. An empty set is not a fault: the registry has no records until a kind
 * brings its own.
 *
 * @param {RegistryItem[]} items
 * @param {Readonly<Record<string, KindSpec>>} [kinds]
 * @returns {string[]}
 */
export function registrySetErrors(items, kinds = KINDS) {
  /** @type {string[]} */
  const errors = [];
  /** @type {Map<string, string>} */
  const names = new Map();
  for (const { kind, id, name } of items) {
    const key = `${kind}\u0000${foldText(name)}`;
    const other = names.get(key);
    if (other !== undefined) errors.push(`${kind}/${id} and ${kind}/${other} are both named "${name}"`);
    else names.set(key, id);
  }
  for (const [kind, spec] of Object.entries(kinds)) {
    const mine = items.filter((item) => item.kind === kind);
    if (spec.setErrors) errors.push(...spec.setErrors(mine));
  }
  return errors;
}

/**
 * The items in the site's order: kinds as they are defined, then name folded so case and accents do not matter.
 *
 * @param {RegistryItem[]} items
 * @param {Readonly<Record<string, KindSpec>>} [kinds]
 */
export function sortRegistry(items, kinds = KINDS) {
  const order = new Map(kindKeys(kinds).map((kind, i) => [kind, i]));
  return [...items].sort(
    (a, b) =>
      (order.get(a.kind) ?? 0) - (order.get(b.kind) ?? 0) ||
      foldText(a.name).localeCompare(foldText(b.name), "en", { numeric: true }),
  );
}

/**
 * An item from a row of the table: the shared columns, and the kind's fields from `record`.
 *
 * @param {{ kind: string, id: string, name: string, status: string, record: string }} row
 * @returns {RegistryItem}
 */
export function itemFromRow(row) {
  return {
    kind: row.kind,
    id: row.id,
    name: row.name,
    status: row.status === "draft" ? "draft" : "published",
    fields: JSON.parse(row.record),
  };
}

app/kb/registry/search-inputs.mjs.source:
// What the site's search finds for a registry item (docs/REGISTRY.md): one record per published item, so a search for a primer's
// sequence, its target, its reference or the paper that prints it finds the primer's own page as well as the protocols that use
// it. The record is derived from the item and nothing else, so a save, sync_registry and sync:content write the same text, and a
// draft has none. Like a paper's, it is one record with no deep links: an item has no sections to link to.

import { itemPath, primerRow, siteText } from "./catalog.mjs";
import { stated } from "./primer.mjs";
import { designationOf } from "./strain.mjs";

/** The item's search uid: a removal needs it to find the item's record. @param {string} kind @param {string} id */
export function registrySearchUid(kind, id) {
  // The registry: namespace keeps these uids separable from hand-authored pages and papers when search_docs is pruned.
  return `registry:${kind}/${id}`;
}

/**
 * The words a primer is searched by: what it is, its sequence and reverse complement (a sequence search finds either strand),
 * where it binds, and the paper that prints it. Only facts the record states or computes; a fact that could not be found is
 * not a word to find.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function primerBody(item) {
  const row = primerRow(item);
  return [
    row.name,
    row.direction ? `${row.direction} primer` : "primer",
    row.sequence,
    row.reverseComplement,
    row.target,
    row.set,
    row.length ? `${row.length} nt` : null,
    row.placement ? `${row.placement.reference.id} ${row.placement.reference.description}` : null,
    ...(row.placement ? row.placement.sites.map(siteText) : []),
    row.publishedIn,
    row.publishedDoi,
    row.publishedName,
    row.publishedSequence,
  ]
    .filter(Boolean)
    .join(" ");
}

/**
 * The words a strain is searched by: its organism, designation, collection and number. The phages isolated on it are the
 * phages table's own records and are not copied into this one.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function strainBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [item.name, "strain", "host", stated(f.organism), designationOf(f), stated(f.collection), stated(f.collection_number)].filter(Boolean).join(" ");
}

/**
 * The words a reagent is searched by: its name, what a protocol calls it or makes it of, and where it comes from. A gap is not a
 * word to find.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function reagentBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [item.name, "reagent", stated(f.abbreviation), stated(f.contents), f.prepared_in_lab === true ? "prepared in the lab" : null, stated(f.supplier), stated(f.catalog_number)]
    .filter(Boolean)
    .join(" ");
}

/** The words an item of equipment is searched by: its name, who makes it and a centrifuge's rotor. @param {import("./kinds.mjs").RegistryItem} item */
function equipmentBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [item.name, "equipment", stated(f.manufacturer), stated(f.rotor)].filter(Boolean).join(" ");
}

/** Each kind's search words. A kind with none is not indexed, so a kind added later is not indexed by accident. */
const BODIES = /** @type {Record<string, (item: import("./kinds.mjs").RegistryItem) => string>} */ ({
  primer: primerBody,
  strain: strainBody,
  reagent: reagentBody,
  equipment: equipmentBody,
});

/**
 * The record input of one item, or null for a kind with no search body yet (so a kind added later is not indexed by accident).
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {{ uid: string, url: string, title: string, body: string } | null}
 */
export function registrySearchInput(item) {
  const body = BODIES[item.kind]?.(item) ?? null;
  if (body === null) return null;
  return { uid: registrySearchUid(item.kind, item.id), url: itemPath(item.kind, item.id), title: item.name, body };
}

/** The inputs of every published item that has one, for the build's search artifact. @param {import("./kinds.mjs").RegistryItem[]} items */
export function registrySearchInputs(items) {
  return items.flatMap((item) => {
    if (item.status === "draft") return [];
    const input = registrySearchInput(item);
    return input ? [input] : [];
  });
}

app/lib/content/og-card-text.mjs.source:
// Its own module because ogImageKey must hash the same clamped strings the card draws, and because a
// route names a page's card through it without importing the markdown renderer. Characters stand in
// for width, so every number here was measured off rendered cards.

import { fnv1a32 } from "../fingerprint.mjs";
import { longDateUTC } from "../long-date.mjs";
import { ASSET_PREFIX } from "../media/classify.mjs";

export const TITLE_MAX = 150;

/**
 * Measured off rendered 1200x630 cards against the layout in build-og.mjs.
 *
 * @type {ReadonlyArray<{ maxChars: number, fontSize: number }>}
 */
export const TITLE_SIZES = [
  { maxChars: 72, fontSize: 72 },
  { maxChars: 110, fontSize: 54 },
  { maxChars: TITLE_MAX, fontSize: 42 },
];

// Two lines of description, enforced here because satori's WebkitLineClamp does nothing.
export const DESCRIPTION_MAX = 132;

// Dashes as escapes in a string: a hook bans those characters from the repo's bytes.
const DANGLING_PUNCTUATION = new RegExp("[,;:.\\u2014\\u2013-]+$");

/**
 * A single word longer than max is still cut: running off the card is worse.
 *
 * @param {string | null | undefined} value
 * @param {number} max
 * @returns {string}
 */
export function clampWords(value, max) {
  const text = (value ?? "").trim();
  if (text.length <= max) return text;
  const cut = text.slice(0, max);
  const lastSpace = cut.lastIndexOf(" ");
  const kept = lastSpace > 0 ? cut.slice(0, lastSpace) : cut;
  return `${kept.replace(DANGLING_PUNCTUATION, "")}…`;
}

/**
 * @param {string | null | undefined} title
 * @returns {string}
 */
export function cardTitle(title) {
  return clampWords(title, TITLE_MAX);
}

/**
 * @param {string | null | undefined} description
 * @returns {string}
 */
export function cardDescription(description) {
  return clampWords(description, DESCRIPTION_MAX);
}

/**
 * Throws, never falls back: a title past the last rung means TITLE_MAX and the ladder disagree.
 *
 * @param {string} title the title AS DRAWN, i.e. already through `cardTitle`
 * @returns {number}
 */
export function titleFontSize(title) {
  const length = (title ?? "").length;
  for (const rung of TITLE_SIZES) {
    if (length <= rung.maxChars) return rung.fontSize;
  }
  throw new Error(
    `og-card-text: a ${length}-character title is past the last rung of the ` +
      `ladder (${TITLE_MAX}). Titles must go through cardTitle() first.`,
  );
}

// Bump on any card template change: the key hashes only the card's inputs, and an immutable cache
// ignores a restyled PNG under an unchanged key forever.
const OG_TEMPLATE_VERSION = 6;

/**
 * Hashes exactly what the card draws, AS DRAWN (through cardTitle, cardDescription, longDateUTC), so
 * the key changes when the picture would and never otherwise. FNV-1a: identical in Node and a Worker,
 * and this is a cache-busting key, not a security boundary.
 *
 * @param {{
 *   slug: string,
 *   title: string,
 *   description?: string | null,
 *   publishAt?: string | null,
 * }} post
 */
export function ogImageKey(post) {
  const drawnDate = longDateUTC(post.publishAt);
  const input =
    `${OG_TEMPLATE_VERSION}\n${post.slug}\n${cardTitle(post.title)}\n` +
    `${cardDescription(post.description)}\n${drawnDate === null ? "" : drawnDate}`;
  return `og/${ASSET_PREFIX}${post.slug}-${fnv1a32(input)}.png`;
}

app/lib/cv/parse.mjs.source:
// Where the CV's files are and what each holds (docs/CV.md). Pure: the registry the save, the sync, the build
// and the drift check share, so none of them names a file the others do not.

/** The repository directory the CV lives in, one markdown file per section plus the profile. */
export const CV_DIR = "content/cv";

/**
 * The files, in the order their entries make the CV's flat list (traditional CV order, which is also the
 * page's "by type" sort). `type` is the entry type a section file holds; the profile holds none.
 *
 * @type {ReadonlyArray<{ slug: string, type: import("./types.ts").CvType | "profile" }>}
 */
export const CV_FILES = [
  { slug: "profile", type: "profile" },
  { slug: "appointments", type: "appointment" },
  { slug: "education", type: "education" },
  { slug: "publications", type: "publication" },
  { slug: "grants", type: "grant" },
  { slug: "honors", type: "award" },
  { slug: "talks", type: "talk" },
  { slug: "courses", type: "course" },
  { slug: "mentoring", type: "mentoring" },
  { slug: "service", type: "service" },
  { slug: "development", type: "development" },
];

/** @param {string} slug */
export function cvSourcePath(slug) {
  return `${CV_DIR}/${slug}.md`;
}

/**
 * The file a slug names, or undefined. A save cannot create a file: the set of files is structure, so a
 * new one is a change to CV_FILES and to the code that reads it.
 *
 * @param {string} slug
 */
export function cvFileFor(slug) {
  return CV_FILES.find((file) => file.slug === slug);
}

app/lib/dictionary-entries.mjs.source:
/**
 * How a dictionary entry reads on each surface. The entries themselves are files, content/dictionary/<key>.md
 * (docs/DICTIONARY.md), compiled by app/lib/dictionary/compile.mjs and drawn from D1 (the dictionary_entries
 * table) at request time; this module only turns one entry into the page's lead, the markdown twin's lead, the
 * search record's sentences and the DefinedTerm JSON-LD, so people and machines read the same entry.
 *
 * Each name is a real English word most readers rarely meet, so the page first says what the word means, then
 * what the software is. Sense 1 follows the dictionaries; sense 2 is the software, plain and factual, and
 * carries the subject label "software." in italics, as a dictionary marks a specialized sense.
 */

import { thing } from "@drdustinedwards/site-helpers/schema";

/**
 * An etymology is text with foreign words marked, so the page can set them in italics with their
 * language and the twin can emphasize them: a string is plain text, a pair is [lang, word].
 *
 * @typedef {string | [string, string]} EtymologyPart
 * @typedef {{
 *   path: string,
 *   term: string,
 *   syllables: string,
 *   ipa: string,
 *   respelling: string,
 *   partOfSpeech: string,
 *   plural: string[] | null,
 *   etymology: EtymologyPart[],
 *   senses: [string, string],
 *   senseLabels: [string | null, string | null],
 *   audio: string,
 * }} DictionaryEntry
 */

/** The subject label on each software sense (Dustin, 2026-09-28), set in italics before it. */
export const SOFTWARE_LABEL = "software";

/** @param {string | null | undefined} label */
function labelPrefix(label) {
  return label ? `${label}. ` : "";
}

/** @param {string} term */
export function listenLabel(term) {
  return `Listen to the pronunciation of ${term}`;
}

/** @param {DictionaryEntry} entry */
function etymologyText(entry) {
  return entry.etymology.map((part) => (typeof part === "string" ? part : part[1])).join("");
}

/**
 * The entry as plain sentences, for the search record, where markup would be noise.
 *
 * @param {DictionaryEntry} entry
 */
export function dictionaryEntryText(entry) {
  const plural = entry.plural ? `; plural ${entry.plural.join(" or ")}` : "";
  return [
    `${entry.term} (${entry.syllables}), ${entry.ipa}, ${entry.respelling}, ${entry.partOfSpeech}${plural}.`,
    ...entry.senses.map((sense, i) => `${i + 1}. ${labelPrefix(entry.senseLabels[i])}${sense}`),
    `Etymology: ${etymologyText(entry)}`,
  ].join(" ");
}

/**
 * The entry in the markdown twin, directly under the title, the same place the page shows it.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin absolute origin for the audio link, so the twin read alone still resolves
 */
export function dictionaryEntryMarkdown(entry, origin = "") {
  const plural = entry.plural ? `; plural ${entry.plural.map((form) => `*${form}*`).join(" or ")}` : "";
  const etymology = entry.etymology.map((part) => (typeof part === "string" ? part : `*${part[1]}*`)).join("");
  return [
    `**${entry.syllables}** ${entry.ipa} (${entry.respelling}), *${entry.partOfSpeech}*${plural}. [Pronunciation audio](${origin}${entry.audio})`,
    "",
    ...entry.senses.map((sense, i) => {
      const label = entry.senseLabels[i];
      return `${i + 1}. ${label ? `*${label}.* ` : ""}${sense}`;
    }),
    "",
    `Etymology: ${etymology}`,
    "",
  ].join("\n");
}

/**
 * schema.org DefinedTerm: the name, sense 2 as the description (what the word means on this page),
 * and the set every entry belongs to, which is the Software hub.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin
 */
export function definedTermJsonLd(entry, origin) {
  return thing("DefinedTerm", {
    name: entry.term,
    description: entry.senses[1],
    url: `${origin}${entry.path}`,
    inDefinedTermSet: {
      "@type": "DefinedTermSet",
      name: "Software names on dustinedwards.info",
      url: `${origin}/software`,
    },
  });
}

app/lib/health/ask-converge.mjs.source:
/**
 * One row of /api/health, as ship and the watchdog read it. `waitedMs` is set only by settleAskDrift.
 *
 * @typedef {{ name?: string, ok?: boolean, expected?: number, present?: number, waitedMs?: number }} HealthCheckRow
 */

export const ASK_POLL_ATTEMPTS = 12;
export const ASK_POLL_INTERVAL_MS = 10_000;
export const ASK_POLL_WINDOW_MS = 120_000;

/**
 * @param {object} options
 * @param {() => Promise<{ ok: boolean, expected?: number, present?: number } | null>} options.reading
 * @param {(ms: number) => Promise<unknown>} options.sleep
 * @param {() => number} [options.now]
 * @param {number} [options.attempts]
 * @param {number} [options.intervalMs]
 * @param {number} [options.windowMs]
 * @param {(event: { poll: number, reading: any, error: string | null }) => void} [options.onPoll]
 * @returns {Promise<{ converged: boolean, polls: number, latest: any, lastError: string | null }>}
 */
export async function awaitAskConvergence({
  reading,
  sleep,
  now = Date.now,
  attempts = ASK_POLL_ATTEMPTS,
  intervalMs = ASK_POLL_INTERVAL_MS,
  windowMs = ASK_POLL_WINDOW_MS,
  onPoll = () => {},
}) {
  const deadline = now() + windowMs;
  /** @type {any} */
  let latest = null;
  let polls = 0;
  /** A thrown read is an unreadable poll, and its reason is carried out rather than dropped. */
  /** @type {string | null} */
  let lastError = null;

  for (let i = 0; i < attempts && now() < deadline; i += 1) {
    await sleep(intervalMs);
    polls += 1;

    /** @type {any} */
    let observed = null;
    /** @type {string | null} */
    let error = null;
    try {
      observed = await reading();
    } catch (thrown) {
      // A failing HTTP status is not this: it is a readable answer, and the caller parses the body.
      error = thrown instanceof Error ? thrown.message : String(thrown);
      lastError = error;
    }

    const usable = observed && typeof observed.ok === "boolean" ? observed : null;
    if (usable) latest = usable;
    onPoll({ poll: polls, reading: usable, error });

    if (usable && usable.ok) return { converged: true, polls, latest, lastError };
  }

  return { converged: false, polls, latest, lastError };
}

/**
 * Ship's post-repair assertion reads health seconds after the Ask upload, and the index can list
 * short then even when the upload's own write-back read was full (157 then 155, deploy run
 * 36274700184). A failing row gets the same bounded window as the write-back; one that converges
 * is ok, and one that does not keeps its latest counts and the time waited, for the miss.
 *
 * @param {object} options
 * @param {HealthCheckRow | undefined} options.row the ask-index-drift row
 * @param {() => Promise<{ ok: boolean, expected?: number, present?: number } | null>} options.reading
 * @param {(ms: number) => Promise<unknown>} options.sleep
 * @param {() => number} [options.now]
 * @param {(event: { poll: number, reading: any, error: string | null }) => void} [options.onPoll]
 * @returns {Promise<HealthCheckRow | undefined>}
 */
export async function settleAskDrift({ row, reading, sleep, now = Date.now, onPoll }) {
  if (!row || row.ok === true) return row;

  const started = now();
  const { converged, latest } = await awaitAskConvergence({ reading, sleep, now, onPoll });
  // The row's own counts are the stale ones; a converged row carries none, as health's ok rows do.
  if (converged) return { name: row.name, ok: true };
  const counts =
    latest && typeof latest.expected === "number" && typeof latest.present === "number"
      ? { expected: latest.expected, present: latest.present }
      : {};
  return { ...row, ...counts, waitedMs: now() - started };
}

app/lib/identity.mjs.source:
// The owner's identity, derived from the CV (docs/CV.md): the one-line role, the Person record's job title, the
// headship, the department and the university. content/cv/profile.md holds the person (name, degree, discipline,
// department, organization) and content/cv/appointments.md holds what he is appointed to, so a change to either
// changes every place the site states them: the site settings (app/lib/seo.ts), page titles, the About text, the
// CV's own header and the structured data. scripts/build-identity.mjs runs this over the files at build and
// writes app/lib/identity.generated.mjs, which those places import.
//
// Pure and dependency-free, so the build, the CV compile and the tests share one definition.

/** The CV's section of ranks and positions, and its section of headships and other leadership. */
const POSITIONS_SECTION = "Positions";
const ADMIN_SECTION = "Administrative and leadership";

/**
 * "a", "a and b", "a, b, and c".
 *
 * @param {string[]} items
 */
export function joinList(items) {
  if (items.length <= 1) return items.join("");
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(", ")}, and ${items[items.length - 1]}`;
}

/**
 * @typedef {{ name: string, degree: string, discipline: string, department: string, org: string }} IdentityPerson
 * @typedef {{ type?: string, section?: string, title?: string, endYear?: number | "present" | null, headline?: boolean }} IdentityEntry
 *
 * @typedef {{
 *   name: string,
 *   degree: string,
 *   discipline: string,
 *   disciplineLower: string,
 *   rank: string,
 *   role: string,
 *   adminTitles: string[],
 *   adminTitle: string,
 *   jobTitle: string,
 *   cvTitle: string,
 *   department: string,
 *   departmentSubject: string,
 *   org: string,
 *   affiliation: string,
 * }} Identity
 */

/**
 * What the CV states he is now: the one current position (its rank is the first half of the role), every current
 * administrative title (the headship), and the person's discipline (the second half). Returns every problem, so
 * a CV edit that would leave the site with no role is refused where it is made.
 *
 * `role` is "<rank> and <discipline>" ("Professor and Virologist"). `jobTitle` is the Person record's, which also
 * carries the headship ("Virologist, Professor, and Department Head"). `cvTitle` is the CV header's line.
 *
 * @param {IdentityPerson} person
 * @param {IdentityEntry[]} entries every CV entry; only the appointments are read
 * @returns {{ ok: false, errors: string[] } | { ok: true, identity: Identity }}
 */
export function deriveIdentity(person, entries) {
  /** @type {string[]} */
  const errors = [];
  const current = (/** @type {string} */ section, /** @type {boolean} */ headlineOnly) =>
    entries
      .filter(
        (e) =>
          e.type === "appointment" &&
          e.section === section &&
          e.endYear === "present" &&
          typeof e.title === "string" &&
          (!headlineOnly || e.headline === true),
      )
      .map((e) => /** @type {string} */ (e.title));
  const positions = current(POSITIONS_SECTION, false);
  // Only the leadership entries marked `headline: true` are stated beside the role; the rest stay on the CV alone.
  const adminTitles = current(ADMIN_SECTION, true);
  if (positions.length !== 1) {
    errors.push(
      `the CV states ${positions.length} current positions (section "${POSITIONS_SECTION}", endYear present); the site's one-line role is built from exactly one`,
    );
  }
  for (const key of /** @type {const} */ (["name", "degree", "discipline", "department", "org"])) {
    if (typeof person?.[key] !== "string" || person[key].trim() === "") errors.push(`the profile's person.${key} is missing`);
  }
  if (errors.length > 0) return { ok: false, errors };

  const rank = /** @type {string} */ (positions[0]);
  const role = `${rank} and ${person.discipline}`;
  return {
    ok: true,
    identity: {
      name: person.name,
      degree: person.degree,
      discipline: person.discipline,
      disciplineLower: person.discipline.toLowerCase(),
      rank,
      role,
      adminTitles,
      adminTitle: joinList(adminTitles),
      jobTitle: joinList([person.discipline, rank, ...adminTitles]),
      cvTitle: [role, ...adminTitles].join(", "),
      department: person.department,
      departmentSubject: person.department.replace(/^Department of /, ""),
      org: person.org,
      // The university alone: the profile's organization carries its system after a comma.
      affiliation: (person.org.split(",")[0] ?? person.org).trim(),
    },
  };
}

app/lib/media/template-refs.mjs.source:
// Runs at BUILD time and ships as a committed artifact: the Worker has no repository, and its ASSETS
// binding can only fetch. The match is LITERAL, so a constructed path like `/diagrams/${id}.svg` is
// invisible; that is why the library says "no reference found" rather than "unused".

// `content/posts` is absent: post citations belong to the other tracker, and an asset must not claim both.
export const SOURCE_ROOTS = ["app", "workers"];

export const SOURCE_FILES = ["content/features.json"];

// Each paper's file names its PDF by path (`pdfPath`) and each dictionary entry its pronunciation clip (`audio`), so
// these markdown files are sources: without them every hosted PDF and clip would read as unreferenced. Passed
// through unstripped, like JSON: the extracted text has apostrophes. Each cohort's file under content/roster names its
// photograph by path, so without it the nine photographs would read as unreferenced.
export const SOURCE_DIRECTORIES = ["content/publications", "content/dictionary", "content/roster"];

const SOURCE_EXTENSIONS = [".ts", ".tsx", ".mjs", ".js", ".css", ".json", ".webmanifest"];

// Checked first because `SOURCE_FILES` bypass the root rule. `assets.json` lists every asset path.
const SELF_REFERENTIAL = ["content/generated/assets.json"];

/**
 * @param {string} file repo-relative, forward slashes
 * @returns {boolean}
 */
export function isSourceFile(file) {
  if (SELF_REFERENTIAL.includes(file)) return false;
  if (SOURCE_FILES.includes(file)) return true;
  if (SOURCE_DIRECTORIES.some((dir) => file.startsWith(`${dir}/`) && file.endsWith(".md"))) return true;
  const root = file.split("/")[0] ?? "";
  if (!SOURCE_ROOTS.includes(root)) return false;
  return SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext));
}

/**
 * Prose about an asset is not a reference. A tokenizer, not a regex: stripping from `//` to end of line
 * would destroy every `https://` inside a string literal, which is where real references live.
 *
 * @param {string} text
 * @param {boolean} [cssOnly] true for `.css`, which has no line comments
 * @returns {string} the same length, with comment bytes blanked to spaces
 */
export function stripComments(text, cssOnly = false) {
  let out = "";
  let i = 0;
  /** @type {"code"|"line"|"block"|"'"|"\""|"`"} */
  let mode = "code";
  while (i < text.length) {
    const c = text[i];
    const next = text[i + 1];
    if (mode === "code") {
      if (c === "/" && next === "*") { mode = "block"; out += "  "; i += 2; continue; }
      if (!cssOnly && c === "/" && next === "/") { mode = "line"; out += "  "; i += 2; continue; }
      if (!cssOnly && (c === "'" || c === '"' || c === "`")) { mode = c; out += c; i += 1; continue; }
      if (cssOnly && (c === "'" || c === '"')) { mode = c; out += c; i += 1; continue; }
      out += c; i += 1; continue;
    }
    if (mode === "line") {
      if (c === "\n") { mode = "code"; out += c; i += 1; continue; }
      // Blanked rather than deleted, so offsets stay comparable and lines cannot join.
      out += " "; i += 1; continue;
    }
    if (mode === "block") {
      if (c === "*" && next === "/") { mode = "code"; out += "  "; i += 2; continue; }
      out += c === "\n" ? c : " "; i += 1; continue;
    }
    if (c === "\\") { out += text.slice(i, i + 2); i += 2; continue; }
    if (c === mode) { mode = "code"; out += c; i += 1; continue; }
    out += c; i += 1;
  }
  return out;
}

/**
 * Both ends must be boundaries: `/dustin-edwards-logo.svg` is a prefix of `/dustin-edwards-logo-dark.svg`,
 * and `"public/site.webmanifest"` ends with `/site.webmanifest`.
 *
 * @param {string} text the file contents
 * @param {string[]} assetPaths every known asset path
 * @returns {string[]} the subset referenced, in the order given
 */
export function referencesIn(text, assetPaths) {
  return assetPaths.filter((asset) => {
    let from = 0;
    for (;;) {
      const at = text.indexOf(asset, from);
      if (at < 0) return false;
      const before = at === 0 ? undefined : text[at - 1];
      const after = text[at + asset.length];
      /** @param {string | undefined} ch */
      const bounded = (ch) => ch === undefined || !/[A-Za-z0-9._~/-]/.test(ch);
      if (bounded(before) && bounded(after)) return true;
      from = at + 1;
    }
  });
}

/**
 * Sorted, so the generated artifact does not churn with directory order and a gate can byte-compare it.
 *
 * @param {Array<{ file: string, assets: string[] }>} scanned
 * @returns {{ generated: number, refs: Record<string, string[]> }}
 */
export function foldRefs(scanned) {
  /** @type {Record<string, string[]>} */
  const refs = {};
  for (const { file, assets } of scanned) {
    for (const asset of assets) {
      if (!refs[asset]) refs[asset] = [];
      if (!refs[asset].includes(file)) refs[asset].push(file);
    }
  }
  /** @type {Record<string, string[]>} */
  const sorted = {};
  for (const asset of Object.keys(refs).sort()) sorted[asset] = (refs[asset] ?? []).slice().sort();
  return { generated: Object.keys(sorted).length, refs: sorted };
}

