import { SLUG_PATTERN } from "../content/slug.mjs";

// Pure so node:test can reach it (the route imports `~/lib/context`). Allowed origins are passed in, never
// a constant: the site answers on two hosts across the cutover. The slug uses the imported `SLUG_PATTERN`;
// a local regex would fail silently in the permissive direction.

const BLOG_PREFIX = "/writing/";

/**
 * Null for every rejection: distinct refusals would let a caller map this site's URL space.
 *
 * @param {string} target the `target` field, verbatim
 * @param {readonly string[]} allowedOrigins origins this site answers on
 * @returns {string | null} the post slug, or null
 */
export function targetSlug(target, allowedOrigins) {
  let url;
  try {
    url = new URL(target);
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  if (!allowedOrigins.includes(url.origin)) return null;

  // `new URL` has already resolved dot segments and decoded the path, so only prefix and shape remain.
  if (!url.pathname.startsWith(BLOG_PREFIX)) return null;
  const rest = url.pathname.slice(BLOG_PREFIX.length);
  // A trailing slash is the same post; anything with a further segment is not.
  const slug = rest.endsWith("/") ? rest.slice(0, -1) : rest;
  if (!SLUG_PATTERN.test(slug)) return null;
  return slug;
}

/**
 * IPv6 reaches `hostname` bracketed. `http://2130706433/` stays all digits, so the digits arm catches it.
 *
 * @param {string} hostname
 */
function isIpLiteral(hostname) {
  if (hostname.startsWith("[")) return true;
  if (/^[0-9]+$/.test(hostname)) return true;
  return /^[0-9]{1,3}(?:\.[0-9]{1,3}){3}$/.test(hostname);
}

/**
 * RFC 6761 reserves the whole `.localhost` tree, and some resolvers honor it.
 *
 * @param {string} hostname
 */
function isLoopbackName(hostname) {
  const host = hostname.toLowerCase();
  return host === "localhost" || host.endsWith(".localhost");
}

const SOURCE_REFUSALS = {
  unparseable: "source is not an absolute URL",
  protocol: "source must be http or https",
  selfOrigin: "source must be another site",
  ipLiteral: "source must name a host, not an IP address",
  loopback: "source must not be a loopback address",
  sameAsTarget: "source and target must differ",
};

/**
 * The verifier fetches the source, so these refusals bound SSRF. NOT a complete defense: public DNS can
 * resolve to a private address. The runtime bounds the rest: a Worker's `fetch` has no private network
 * or metadata endpoint, and the verifier reads at most 1 MB and stores no markup.
 *
 * @param {string} source the `source` field, verbatim
 * @param {string} target the `target` field, verbatim
 * @param {readonly string[]} allowedOrigins origins this site answers on
 * @returns {{ ok: true } | { ok: false, reason: string }}
 */
export function sourceVerdict(source, target, allowedOrigins) {
  let url;
  try {
    url = new URL(source);
  } catch {
    return { ok: false, reason: SOURCE_REFUSALS.unparseable };
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    return { ok: false, reason: SOURCE_REFUSALS.protocol };
  }
  if (allowedOrigins.includes(url.origin)) {
    return { ok: false, reason: SOURCE_REFUSALS.selfOrigin };
  }
  if (isLoopbackName(url.hostname)) {
    return { ok: false, reason: SOURCE_REFUSALS.loopback };
  }
  if (isIpLiteral(url.hostname)) {
    return { ok: false, reason: SOURCE_REFUSALS.ipLiteral };
  }
  if (source === target) {
    return { ok: false, reason: SOURCE_REFUSALS.sameAsTarget };
  }
  return { ok: true };
}

/**
 * A trailing slash and the fragment are ignored; the QUERY is not, because a query can name a different
 * document (the `/writing` index filters with one).
 *
 * @param {string} href an absolute URL, already resolved against the source
 * @param {string} target the target URL
 */
export function sameDocument(href, target) {
  let a;
  let b;
  try {
    a = new URL(href);
    b = new URL(target);
  } catch {
    return false;
  }
  const strip = (/** @type {URL} */ u) =>
    `${u.origin}${u.pathname.endsWith("/") ? u.pathname.slice(0, -1) : u.pathname}${u.search}`;
  return strip(a) === strip(b);
}

// One owner; the schema comment points here.
const EXCERPT_MAX_CHARS = 280;

/**
 * Plain text by construction: the caller passes `textContent`. This is not a sanitizer.
 *
 * @param {string} text
 */
export function collapseExcerpt(text) {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > EXCERPT_MAX_CHARS ? flat.slice(0, EXCERPT_MAX_CHARS) : flat;
}

/**
 * Checked again at RENDER: a row can outlive the code that wrote it or be hand-written, and a wrong `href`
 * is executable. Null means render the name without a link. Returns the parser's output, not the input.
 *
 * @param {string | null | undefined} value
 * @returns {string | null}
 */
export function safeHttpHref(value) {
  if (!value) return null;
  let url;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  return url.href;
}

app/kb/procedures/cite.mjs.source:
// How a procedure version is addressed and cited: the address of its frozen copy, the citation line, the BibTeX
// entry and the metadata Zenodo takes for a deposit. All of it is derived from the record (its path, its version,
// its history and its title), never typed, so a version bumped in the file changes every place that cites it.
//
// A procedure with no version cannot be cited: a DOI is minted only for a version being cited (decisions.md,
// Protocols), so there is nothing to cite until one has been assigned. The DOI of a version is written once, on that version's
// entry in `history`, after Zenodo has minted it; this module never invents one.
//
// A cited version is a frozen copy (drizzle/0027_procedure_versions.sql), so a citation and a printed sheet's QR
// code point at `<page>/v/<version>`, which never changes, and not at the page, which moves on to the next version.

import { METHODS } from "./taxonomy.mjs";

/**
 * @typedef {{ name: string, affiliation: string }} Creator
 * @typedef {{ version: string, date: string, doi: string | null }} CiteFacts
 */

/** The shape Zenodo's DOIs and DataCite's share: the registrant prefix, a slash, the suffix. */
export const DOI_PATTERN = /^10\.\d{4,9}\/\S+$/;

/** A version that can sit in a URL and a file name: letters, digits, dots, hyphens and underscores. */
export const VERSION_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

/**
 * The path of a version's frozen copy. The newest version also answers here, so a citation made today still
 * resolves to the same words when the page has moved on.
 *
 * @param {string} path the procedure's own path
 * @param {string} version
 */
export function versionPath(path, version) {
  return `${path}/v/${encodeURIComponent(version)}`;
}

/**
 * Whether saving this record freezes a copy: a published procedure with an assigned version. A draft is never
 * frozen, and a procedure with no version has no version to freeze.
 *
 * @param {{ draft: boolean, version: string | null }} record
 */
export function needsFreeze(record) {
  return !record.draft && record.version !== null && record.version !== "";
}

/**
 * The address a printed sheet's QR code opens, and the sheet prints: the frozen copy of the version on it, so the code
 * opens the words the sheet was printed from even after the page has moved on. A procedure with no published version
 * has no copy, so its sheet points at the page.
 *
 * @param {{ draft: boolean, version: string | null, path: string }} record
 * @param {string} origin
 */
export function sheetAddress(record, origin) {
  return `${origin}${needsFreeze(record) ? versionPath(record.path, String(record.version)) : record.path}`;
}

/**
 * What a citation of the record's current version needs, or null when it has no version or no date to cite.
 * The date is the one the history gives the version, else the date the page was last updated.
 *
 * @param {{ version: string | null, updated: string | null, history?: Array<{ version: string, date: string, doi: string | null }> }} record
 * @returns {CiteFacts | null}
 */
export function citeFacts(record) {
  if (!record.version) return null;
  const entry = record.history?.find((h) => h.version === String(record.version));
  const date = entry?.date ?? record.updated;
  if (!date) return null;
  return { version: String(record.version), date, doi: entry?.doi ?? null };
}

/**
 * "Dustin Edwards" as the family name and the given name. For a name written given-first, as the CV writes
 * the owner's; the last word is the family name.
 *
 * @param {string} name
 */
export function familyGiven(name) {
  const words = name.trim().split(/\s+/);
  const family = words.pop() ?? "";
  return { family, given: words.join(" ") };
}

/** @param {string} given */
const initials = (given) =>
  given
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => `${w.charAt(0).toUpperCase()}.`)
    .join(" ");

/**
 * The address a citation points at: the version's DOI when it has one, else its frozen copy.
 *
 * @param {{ path: string }} record
 * @param {CiteFacts} facts
 * @param {string} origin
 */
const target = (record, facts, origin) => (facts.doi ? `https://doi.org/${facts.doi}` : `${origin}${versionPath(record.path, facts.version)}`);

/**
 * @param {{ title: string, path: string }} record
 * @param {CiteFacts} facts
 * @param {{ origin: string, creator: Creator }} where
 */
export function citationText(record, facts, { origin, creator }) {
  const { family, given } = familyGiven(creator.name);
  const host = new URL(origin).host;
  return `${family}, ${initials(given)} (${facts.date.slice(0, 4)}). ${record.title} (Version ${facts.version}) [Laboratory protocol]. ${host}. ${target(record, facts, origin)}`;
}

/**
 * @param {{ slug: string, title: string, path: string }} record
 * @param {CiteFacts} facts
 * @param {{ origin: string, creator: Creator }} where
 */
export function bibtex(record, facts, { origin, creator }) {
  const { family, given } = familyGiven(creator.name);
  const year = facts.date.slice(0, 4);
  const field = (/** @type {string} */ name, /** @type {string} */ value) => `  ${name} = {${value.replace(/[{}]/g, "")}},`;
  return [
    `@misc{${family.toLowerCase()}${year}${record.slug}v${facts.version.replace(/[^A-Za-z0-9.]/g, "")},`,
    field("author", `${family}, ${given}`),
    field("title", record.title),
    field("year", year),
    field("version", facts.version),
    field("howpublished", "Laboratory protocol"),
    ...(facts.doi ? [field("doi", facts.doi)] : []),
    field("url", target(record, facts, origin)),
    "}",
  ].join("\n");
}

/**
 * The metadata for depositing this version on Zenodo (its `.zenodo.json` or its upload form). No `doi` is
 * written: Zenodo mints it, and the maintainer then records it on the version's `history` entry. Earlier
 * versions that already have a DOI are linked as the ones this supersedes. The license is left out: it is
 * Dustin's to choose, and Zenodo asks for it at upload.
 *
 * @param {{ title: string, description: string, path: string, methods: string[], basedOn: Array<{ doi: string | null }>, history?: Array<{ version: string, date: string, doi: string | null }> }} record
 * @param {CiteFacts} facts
 * @param {{ origin: string, creator: Creator }} where
 */
export function zenodoMetadata(record, facts, { origin, creator }) {
  const { family, given } = familyGiven(creator.name);
  const history = record.history ?? [];
  const here = history.findIndex((h) => h.version === facts.version);
  const previous = here >= 0 ? history.slice(here + 1).find((h) => h.doi) : undefined;
  return {
    upload_type: "publication",
    publication_type: "other",
    title: `${record.title} (Version ${facts.version})`,
    description: record.description,
    version: facts.version,
    publication_date: facts.date,
    creators: [{ name: `${family}, ${given}`, affiliation: creator.affiliation }],
    access_right: "open",
    keywords: record.methods.map((id) => /** @type {Record<string, string>} */ (METHODS)[id] ?? id),
    related_identifiers: [
      { identifier: `${origin}${versionPath(record.path, facts.version)}`, relation: "isAlternateIdentifier", scheme: "url" },
      ...(previous?.doi ? [{ identifier: previous.doi, relation: "isNewVersionOf", scheme: "doi" }] : []),
      ...record.basedOn.filter((s) => s.doi).map((s) => ({ identifier: /** @type {string} */ (s.doi), relation: "isDerivedFrom", scheme: "doi" })),
    ],
  };
}

app/kb/procedures/marks.mjs.source:
// The inline marks a procedure step carries, in Cooklang's syntax (https://cooklang.org/docs/spec/):
// `@material{20%µl}`, `#equipment{}`, `~{10%minutes}`, plus the cooklang-rs alias form
// `@material|shown words{20%µl}` and its fixed-amount form `{=20%µl}`. The official parser
// (@cooklang/cooklang) is a pre-1.0 WASM build whose model is recipes only, so the site reads the marks
// itself and keeps Cooklang's spelling, so a file stays readable by Cooklang tools.
//
// Temperatures and spin speeds are read from the words, not marked, so a step stays the sentence a
// person wrote: "Incubate at 55 to 60 °C" is both.

/** A mark starts at the start of the text or after whitespace, so `(#refs)` and `a@b.c` are text. */
const MARK_START = /[@#~]/g;

/** A multi-word name runs to its `{`; it cannot cross another mark, a brace or a line. */
const BRACED = /^([@#])([^@#~{}\n]{1,160}?)\{([^{}\n]*)\}/u;
const SINGLE = /^([@#])([\p{L}\p{N}_-]+)/u;
const TIMER = /^~([^@#~{}\n]{0,60}?)\{([^{}\n]*)\}/u;

/**
 * Stretches of the text where a mark is never read: inline code, a link's target, an autolink.
 *
 * @param {string} text
 * @returns {Array<[number, number]>}
 */
function protectedRanges(text) {
  /** @type {Array<[number, number]>} */
  const ranges = [];
  for (const pattern of [/`[^`\n]*`/g, /\]\([^)\n]*\)/g, /<[a-z]+:[^>\n]*>/gi]) {
    for (const match of text.matchAll(pattern)) ranges.push([match.index, match.index + match[0].length]);
  }
  return ranges;
}

/**
 * A number as written: "20", "1.25", "10,000", "1/2", "1 1/2".
 *
 * @param {string} raw
 * @returns {number | null}
 */
export function parseNumber(raw) {
  const s = raw.trim().replaceAll(",", "");
  let m = /^(\d+) (\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) + Number(m[2]) / Number(m[3]);
  m = /^(\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) / Number(m[2]);
  return /^-?\d+(?:\.\d+)?$/.test(s) ? Number(s) : null;
}

/**
 * The inside of a mark's braces: `20%µl`, `=20%µl`, `1.25 to 5%µl`, `2`, or empty.
 *
 * @param {string} inner
 * @returns {{ raw: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null } | null}
 */
export function parseQuantity(inner) {
  let body = inner.trim();
  if (!body) return null;
  const fixed = body.startsWith("=");
  if (fixed) body = body.slice(1).trim();
  const at = body.indexOf("%");
  const amount = (at < 0 ? body : body.slice(0, at)).trim();
  const unit = at < 0 ? "" : body.slice(at + 1).trim();
  const range = /^(.+?)\s*(?:-|to)\s*(.+)$/.exec(amount);
  const min = parseNumber(range ? range[1] ?? "" : amount);
  const max = range ? parseNumber(range[2] ?? "") : min;
  return { raw: inner, amount, unit, fixed, min, max: min === null ? null : max };
}

/**
 * @typedef {{ type: "text", value: string }} TextSegment
 * @typedef {ReturnType<typeof parseQuantity>} Quantity
 * @typedef {{ type: "material", name: string, display: string, quantity: Quantity }} MaterialSegment
 * @typedef {{ type: "equipment", name: string, display: string }} EquipmentSegment
 * @typedef {{ type: "timer", label: string, quantity: Quantity }} TimerSegment
 * @typedef {TextSegment | MaterialSegment | EquipmentSegment | TimerSegment} Segment
 */

/**
 * Where each mark sits in the text, with the parts it was written with: the one reading of the marks, which tokenize turns
 * into words and the admin editor turns into chips (app/kb/step-marks.mjs), so the two can never split a step differently.
 *
 * @param {string} text
 * @returns {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>}
 */
export function markSpans(text) {
  const ranges = protectedRanges(text);
  const inRange = (/** @type {number} */ i) => ranges.some(([a, b]) => i >= a && i < b);
  /** @type {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>} */
  const out = [];
  let last = 0;
  for (const hit of text.matchAll(MARK_START)) {
    const i = hit.index;
    if (i < last || inRange(i)) continue;
    const before = i === 0 ? "" : (text[i - 1] ?? "");
    if (before && !/\s/.test(before)) continue;
    const rest = text.slice(i);
    if (rest[0] === "~") {
      const m = TIMER.exec(rest);
      if (!m) continue;
      out.push({ start: i, end: i + m[0].length, sign: "~", name: (m[1] ?? "").trim(), shown: "", braces: m[2] ?? "" });
      last = i + m[0].length;
      continue;
    }
    const m = BRACED.exec(rest) ?? SINGLE.exec(rest);
    if (!m) continue;
    const [name, shown] = (m[2] ?? "").split("|").map((part) => part.trim());
    out.push({ start: i, end: i + m[0].length, sign: /** @type {"@" | "#"} */ (m[1]), name: name ?? "", shown: shown ?? "", braces: m[3] === undefined ? null : m[3] });
    last = i + m[0].length;
  }
  return out;
}

/**
 * The text split into words and marks.
 *
 * @param {string} text
 * @returns {Segment[]}
 */
export function tokenize(text) {
  /** @type {Segment[]} */
  const out = [];
  let last = 0;
  for (const span of markSpans(text)) {
    if (span.start > last) out.push({ type: "text", value: text.slice(last, span.start) });
    if (span.sign === "~") out.push({ type: "timer", label: span.name, quantity: parseQuantity(span.braces ?? "") });
    else if (span.sign === "@") {
      out.push({ type: "material", name: span.name, display: span.shown || span.name, quantity: span.braces === null ? null : parseQuantity(span.braces) });
    } else out.push({ type: "equipment", name: span.name, display: span.shown || span.name });
    last = span.end;
  }
  if (text.length > last) out.push({ type: "text", value: text.slice(last) });
  return out;
}

/**
 * A number printed the way the file would write it: no trailing zeros, thousands with commas.
 *
 * @param {number} n
 */
export function formatNumber(n) {
  const rounded = Math.round(n * 1000) / 1000;
  return rounded.toLocaleString("en-US", { maximumFractionDigits: 3 });
}

/**
 * A quantity as words, scaled by `factor` unless it is fixed or not a number.
 *
 * @param {NonNullable<Quantity>} q
 * @param {number} [factor]
 */
export function formatQuantity(q, factor = 1) {
  let amount = q.amount;
  if (factor !== 1 && !q.fixed && q.min !== null) {
    amount =
      q.max !== null && q.max !== q.min
        ? `${formatNumber(q.min * factor)} to ${formatNumber(q.max * factor)}`
        : formatNumber(q.min * factor);
  }
  return q.unit ? `${amount} ${q.unit}` : amount;
}

/**
 * The words a segment stands for on the page.
 *
 * @param {Segment} segment
 * @param {number} [factor]
 */
export function segmentText(segment, factor = 1) {
  switch (segment.type) {
    case "text":
      return segment.value;
    case "material":
      return segment.quantity ? `${formatQuantity(segment.quantity, factor)} of ${segment.display}` : segment.display;
    case "equipment":
      return segment.display;
    case "timer":
      return segment.quantity ? formatQuantity(segment.quantity) : segment.label;
  }
}

/** "37 °C", "55 to 60 °C", "-80 °C", "55-60 °C". Exported for the editor, which shows each as a chip. */
export const TEMPERATURE = /(-?\d+(?:\.\d+)?)(?:\s*(?:to|-)\s*(-?\d+(?:\.\d+)?))?\s*°C/g;
/** "10,000 rpm", "12,000 x g", "10,000 to 15,000 x g". */
const SPIN = /(?<![\d.,])(\d[\d,]*(?:\s*to\s*\d[\d,]*)?)\s*(rpm|x g)\b/g;

/**
 * The temperatures and spins a step's words state.
 *
 * @param {string} text the step with its marks already turned into words
 */
export function readConditions(text) {
  const temperatures = [...text.matchAll(TEMPERATURE)].map((m) => ({
    min: Number(m[1]),
    max: m[2] === undefined ? Number(m[1]) : Number(m[2]),
    text: m[0],
  }));
  const spins = [...text.matchAll(SPIN)].map((m) => ({
    speed: (m[1] ?? "").trim(),
    unit: m[2] === "rpm" ? "rpm" : "x g",
    text: m[0],
  }));
  return { temperatures, spins };
}

app/kb/procedures/run.mjs.source:
// The pure half of run mode (docs/PROCEDURES.md "Run mode"): what a bench run is, how its timers count, and what
// the saved record says. A run is a person working through one procedure once: which steps are done, a note on
// each, the timers they started, the scale they chose. It lives in the browser (localStorage), is downloadable and
// printable, and never reaches the server: nothing here touches the DOM, a clock or storage, so the same functions
// run in a test. The browser module (app/enhance/run.ts) passes `now` in.
//
// A timer's remaining time is computed from the moment it ends, not counted down, so a phone that sleeps or a page
// that reloads mid-incubation still knows how long is left.

import { thing } from "@drdustinedwards/site-helpers/schema";

import { SITE_ORIGIN } from "../../lib/site-origin.mjs";

export const RUN_VERSION = 1;

/** Seconds in each unit a timer mark can use (validate.mjs TIME_UNITS). */
const UNIT_SECONDS = Object.freeze(
  /** @type {Record<string, number>} */ ({
    second: 1, seconds: 1, sec: 1, s: 1,
    minute: 60, minutes: 60, min: 60,
    hour: 3600, hours: 3600, h: 3600,
    day: 86400, days: 86400,
  }),
);

/**
 * @typedef {{ label: string, text: string, min: number | null, max: number | null, unit: string }} StepTimer
 * @typedef {{ state: "running" | "paused" | "done", endsAt: number | null, remainingMs: number, totalMs: number }} TimerState
 * @typedef {{ done: boolean, doneAt: number | null, note: string }} StepState
 * @typedef {{
 *   v: number, path: string, version: string, title: string, scale: number | null,
 *   startedAt: number, finishedAt: number | null, note: string,
 *   steps: Record<string, StepState>, timers: Record<string, TimerState>,
 * }} Run
 */

/**
 * A timer's length in milliseconds: the longer end of a range ("5 to 10 minutes" runs 10), because a timer that
 * rings early is the mistake that costs a prep. Null when the mark carries no usable number.
 *
 * @param {StepTimer} timer
 */
export function timerMs(timer) {
  const seconds = UNIT_SECONDS[String(timer.unit).toLowerCase()];
  const amount = timer.max ?? timer.min;
  if (seconds === undefined || amount === null || !Number.isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * seconds * 1000);
}

/** The key a step's nth timer is stored under. */
export const timerKey = (/** @type {number | string} */ step, /** @type {number} */ index) => `${step}.${index}`;

/**
 * @param {{ path: string, version: string, title: string, scale: number | null }} procedure
 * @param {number} now
 * @returns {Run}
 */
export function newRun(procedure, now) {
  return { v: RUN_VERSION, path: procedure.path, version: procedure.version, title: procedure.title, scale: procedure.scale, startedAt: now, finishedAt: null, note: "", steps: {}, timers: {} };
}

const stepOf = (/** @type {Run} */ run, /** @type {number | string} */ step) => run.steps[String(step)] ?? { done: false, doneAt: null, note: "" };

/** @param {Run} run @param {number | string} step @param {number} now */
export function toggleDone(run, step, now) {
  const current = stepOf(run, step);
  return { ...run, steps: { ...run.steps, [String(step)]: { ...current, done: !current.done, doneAt: current.done ? null : now } } };
}

/** @param {Run} run @param {number | string} step @param {string} note */
export function setNote(run, step, note) {
  return { ...run, steps: { ...run.steps, [String(step)]: { ...stepOf(run, step), note: note.slice(0, 2000) } } };
}

/** @param {Run} run @param {string} note */
export function setRunNote(run, note) {
  return { ...run, note: note.slice(0, 4000) };
}

/** @param {Run} run @param {number | null} scale */
export function setScale(run, scale) {
  return { ...run, scale };
}

/** @param {Run} run @param {number} now */
export function finishRun(run, now) {
  return { ...run, finishedAt: run.finishedAt ?? now };
}

/** Starts a timer, or resumes a paused one from where it stopped. @param {Run} run @param {string} key @param {number} ms @param {number} now */
export function startTimer(run, key, ms, now) {
  const current = run.timers[key];
  const remainingMs = current && current.state === "paused" ? current.remainingMs : ms;
  return { ...run, timers: { ...run.timers, [key]: { state: /** @type {const} */ ("running"), endsAt: now + remainingMs, remainingMs, totalMs: ms } } };
}

/** @param {Run} run @param {string} key @param {number} now */
export function pauseTimer(run, key, now) {
  const current = run.timers[key];
  if (!current || current.state !== "running" || current.endsAt === null) return run;
  return { ...run, timers: { ...run.timers, [key]: { ...current, state: /** @type {const} */ ("paused"), endsAt: null, remainingMs: Math.max(0, current.endsAt - now) } } };
}

/** @param {Run} run @param {string} key */
export function resetTimer(run, key) {
  const { [key]: _gone, ...rest } = run.timers;
  return { ...run, timers: rest };
}

/** Milliseconds left on a timer, or null when it has not been started. @param {Run} run @param {string} key @param {number} now */
export function timerRemaining(run, key, now) {
  const t = run.timers[key];
  if (!t) return null;
  if (t.state === "paused" || t.state === "done") return t.state === "done" ? 0 : t.remainingMs;
  return Math.max(0, (t.endsAt ?? now) - now);
}

/**
 * Marks every running timer whose time has come as done, and returns which rang so the page can alert once.
 *
 * @param {Run} run @param {number} now
 * @returns {{ run: Run, rang: string[] }}
 */
export function tickTimers(run, now) {
  /** @type {string[]} */
  const rang = [];
  /** @type {Record<string, TimerState>} */
  const timers = { ...run.timers };
  for (const [key, t] of Object.entries(run.timers)) {
    if (t.state === "running" && t.endsAt !== null && t.endsAt <= now) {
      timers[key] = { ...t, state: /** @type {const} */ ("done"), endsAt: null, remainingMs: 0 };
      rang.push(key);
    }
  }
  return rang.length === 0 ? { run, rang } : { run: { ...run, timers }, rang };
}

/** "2:05", "1:30:00": a countdown in the form a person reads at the bench. @param {number} ms */
export function clock(ms) {
  const total = Math.ceil(Math.max(0, ms) / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}` : `${m}:${String(s).padStart(2, "0")}`;
}

/** How far along a run is, over the steps the procedure has. @param {Run} run @param {Array<number | string>} steps */
export function runProgress(run, steps) {
  const done = steps.filter((n) => run.steps[String(n)]?.done).length;
  return { done, total: steps.length };
}

/**
 * The step one-at-a-time view shows (docs/KNOWLEDGE-BASE.md, R4, the cook view): the one the person chose, while it is still a
 * step of the procedure; else the first not yet done; else the last, so a finished run still shows a step.
 *
 * @param {Run} run
 * @param {string[]} keys every step's key, in the page's order
 * @param {string | null} chosen
 */
export function shownStep(run, keys, chosen) {
  if (chosen && keys.includes(chosen)) return chosen;
  return keys.find((key) => !run.steps[key]?.done) ?? keys[keys.length - 1] ?? null;
}

/**
 * The step before or after `key`, or null at either end.
 *
 * @param {string[]} keys
 * @param {string} key
 * @param {-1 | 1} by
 */
export function stepBeside(keys, key, by) {
  const at = keys.indexOf(key);
  return at === -1 ? null : (keys[at + by] ?? null);
}

const when = (/** @type {number | null} */ ms) => (ms === null ? "" : new Date(ms).toISOString());

/** The Bioschemas profile a run's download follows (docs/KNOWLEDGE-BASE.md, P4). */
const LAB_PROCESS_PROFILE = "https://bioschemas.org/profiles/LabProcess/0.1-DRAFT";

/**
 * The saved record as a plain object: what a download is, and what survives the browser. Only what the person
 * entered or did, with the procedure's own identity so the record says which version it followed.
 *
 * It is also a Bioschemas LabProcess (P4): runs are private, so this download is the only place one is written. The
 * protocol it executes is named by the `@id` the procedure's page gives its LabProtocol, and its version.
 *
 * A step's `key` is unique in the procedure (its section and its number: numbering restarts in a section that starts
 * its own list), `number` is the one the page prints.
 *
 * @param {Run} run
 * @param {Array<{ key?: string, number: number | string, section?: string, text: string }>} steps
 * @param {string} [origin] the site the run was made on
 */
export function runRecord(run, steps, origin = SITE_ORIGIN) {
  // A run made on a frozen version's page carries its /v/ address; the protocol's identity is its plain page.
  const page = run.path.replace(/\/v\/[^/]+$/, "");
  // The LabProcess node is Prelum's `thing`; the record's own fields follow it as they are, since a null scale or an empty
  // note is part of the saved record's format (RUN_VERSION), not a missing fact.
  return {
    ...thing("LabProcess", {
      "http://purl.org/dc/terms/conformsTo": { "@id": LAB_PROCESS_PROFILE },
      name: `Run of ${run.title}`,
      executesLabProtocol: { "@type": "LabProtocol", "@id": `${origin}${page}#procedure`, name: run.title, url: `${origin}${run.path}`, ...(run.version ? { version: run.version } : {}) },
      startTime: when(run.startedAt),
      ...(run.finishedAt !== null ? { endTime: when(run.finishedAt) } : {}),
      ...(run.note.trim() ? { description: run.note.trim() } : {}),
      ...(run.scale !== null ? { parameterValue: [{ "@type": "PropertyValue", name: "Scale", value: run.scale }] } : {}),
    }),
    record: "dustinedwards.info run",
    format: RUN_VERSION,
    procedure: { path: run.path, title: run.title, version: run.version },
    scale: run.scale,
    startedAt: when(run.startedAt),
    finishedAt: when(run.finishedAt),
    note: run.note,
    steps: steps.map((s) => {
      const st = stepOf(run, s.key ?? s.number);
      return { step: s.number, section: s.section ?? "", text: s.text, done: st.done, doneAt: when(st.doneAt), note: st.note };
    }),
  };
}

/**
 * The same record as plain Markdown, for a notebook or an email: a heading, the run's facts, and each step as a
 * checked or unchecked line with its note under it.
 *
 * @param {Run} run
 * @param {Array<{ key?: string, number: number | string, section?: string, text: string }>} steps
 */
export function runMarkdown(run, steps) {
  const lines = [`# Run: ${run.title}`, ""];
  lines.push(`Protocol: ${run.path}${run.version ? `, version ${run.version}` : ""}`);
  if (run.scale !== null) lines.push(`Scale: ${run.scale}`);
  lines.push(`Started: ${when(run.startedAt)}`);
  if (run.finishedAt !== null) lines.push(`Finished: ${when(run.finishedAt)}`);
  if (run.note.trim()) lines.push("", run.note.trim());
  lines.push("", "## Steps", "");
  let section = "";
  for (const s of steps) {
    if ((s.section ?? "") !== section) {
      section = s.section ?? "";
      if (section) lines.push("", `### ${section}`, "");
    }
    const st = stepOf(run, s.key ?? s.number);
    lines.push(`- [${st.done ? "x" : " "}] ${s.number}. ${s.text.replace(/\s+/g, " ").trim()}${st.done && st.doneAt ? ` (${when(st.doneAt)})` : ""}`);
    if (st.note.trim()) lines.push(`  - Note: ${st.note.trim().replace(/\n+/g, " ")}`);
  }
  return `${lines.join("\n")}\n`;
}

/**
 * Parses a stored run, or returns null: a stored value from another format or one that is not a run is ignored, never
 * trusted. Only the shapes this module writes are accepted.
 *
 * @param {unknown} raw
 * @returns {Run | null}
 */
export function parseRun(raw) {
  if (typeof raw !== "string") return null;
  let value;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!value || typeof value !== "object" || value.v !== RUN_VERSION) return null;
  // typeof null is "object", so a null `steps` must be refused by name.
  const plainObject = (/** @type {unknown} */ x) => x !== null && typeof x === "object" && !Array.isArray(x);
  if (typeof value.path !== "string" || typeof value.startedAt !== "number" || !plainObject(value.steps) || !plainObject(value.timers)) return null;
  return /** @type {Run} */ ({
    v: RUN_VERSION,
    path: value.path,
    version: typeof value.version === "string" ? value.version : "",
    title: typeof value.title === "string" ? value.title : "",
    scale: typeof value.scale === "number" ? value.scale : null,
    startedAt: value.startedAt,
    finishedAt: typeof value.finishedAt === "number" ? value.finishedAt : null,
    note: typeof value.note === "string" ? value.note : "",
    steps: value.steps,
    timers: value.timers,
  });
}

app/kb/registry/kinds.mjs.source:
// The kinds the lab registry holds (docs/REGISTRY.md). A kind is data here, not a branch in the compile: its label,
// its address and the fields it knows beyond the ones every item has (name and status). The compile
// (compile.mjs), the save, the sync, the drift check and Carrel's handlers all read this one object, so a kind
// added here is a kind every one of them serves.
//
// The registry shipped as a framework with no kind (job_915d43f44cee), and each kind arrives with its own records and
// pages in its own change: primer, then strain, then reagent and equipment.

import { EQUIPMENT } from "./equipment.mjs";
import { PRIMER } from "./primer.mjs";
import { REAGENT } from "./reagent.mjs";
import { STRAIN } from "./strain.mjs";

/**
 * What a kind says about one field. `check` returns a message when the value is wrong and null when it is right; it
 * may be async (a field that names a publication asks the host). A value written "MISSING: <why>" is a recorded gap
 * and skips `check`, as in a procedure.
 *
 * @typedef {{
 *   required?: boolean,
 *   check: (value: unknown, context: RegistryContext) => string | null | Promise<string | null>,
 * }} FieldSpec
 *
 * @typedef {{
 *   singular: string,
 *   plural: string,
 *   itemPages?: boolean,
 *   fields: Record<string, FieldSpec>,
 *   setErrors?: (items: RegistryItem[]) => string[],
 * }} KindSpec
 *
 * What the host can answer for a file the repository holds, so the Worker (reading GitHub) and Node (reading the
 * clone) judge a file the same way. `paper` is whether the site holds a publication with that file key, and `recipe` whether the site holds a procedure with the
 * recipe profile under that file key.
 *
 * @typedef {{ paper: (slug: string) => Promise<boolean>, recipe: (slug: string) => Promise<boolean> }} RegistryHost
 * @typedef {{ host: RegistryHost, data: Record<string, unknown> }} RegistryContext
 *
 * One item as the table holds it: the shared columns and the kind's own fields, `null` where a kind's field is
 * absent. `fields` never repeats a shared column.
 *
 * @typedef {{ kind: string, id: string, name: string, status: "published" | "draft", fields: Record<string, unknown> }} RegistryItem
 */

/** @type {Readonly<Record<string, KindSpec>>} */
export const KINDS = Object.freeze({ primer: PRIMER, strain: STRAIN, reagent: REAGENT, equipment: EQUIPMENT });

/** The kinds in the order the site lists them, which is the order they are defined in. @param {Record<string, KindSpec>} [kinds] */
export function kindKeys(kinds = KINDS) {
  return Object.keys(kinds);
}

app/kb/registry/tm.mjs.source:
// A primer's melting temperature, computed from its sequence and never typed (a computable value is computed). The
// method and the conditions are stated on every page that shows a Tm, from the constants below, so a reader knows what
// the number means and a change of condition changes every page at once.
//
// METHOD. The unified nearest-neighbor model of SantaLucia (1998), Proc. Natl. Acad. Sci. USA 95:1460-1465, doi
// 10.1073/pnas.95.4.1460: the duplex's enthalpy and entropy are the sums of its dinucleotide steps plus an initiation
// term for each end, the entropy is corrected for the monovalent salt, and
//
//   Tm = 1000 x dH / (dS + R x ln(C)) - 273.15
//
// with dH in kcal/mol, dS in cal/(K x mol), R = 1.987 cal/(K x mol) and C the primer concentration. C is the primer
// concentration itself, not the total strand concentration over four, because in a PCR the primer is in large excess
// over the template (for strands at unequal concentration the term is C(excess) minus half of C(limiting), which is C when
// the template is far below the primer). A self-complementary primer also takes the symmetry term.
//
// CONDITIONS. 50 mM monovalent cation and 0.5 uM primer, with the template taken as far below the primer. They are the
// usual reporting defaults, not the conditions of any one reaction buffer (a master mix's own salt and Mg2+ shift the
// working Tm), so the figure is for comparing primers with each other. The page says so.
//
// A sequence with an ambiguity code or any base but A, C, G and T has no single Tm, so it has none here: null, never a
// guess. test/registry-tm.test.mjs holds this to Biopython's Bio.SeqUtils.MeltingTemp.Tm_NN (DNA_NN3, which carries the
// SantaLucia 1998 table, saltcorr 5, the template taken as zero).

/** The conditions every Tm on the site is computed under, stored once. */
export const TM_CONDITIONS = Object.freeze({
  /** Monovalent cation, mM. */
  sodiumMM: 50,
  /** Primer, nM. */
  primerNM: 500,
  method: "SantaLucia (1998) unified nearest-neighbor model",
  citation: "SantaLucia J Jr (1998), Proc Natl Acad Sci USA 95:1460-1465",
  doi: "10.1073/pnas.95.4.1460",
});

/** The shortest oligo the model is applied to; a Tm for fewer bases is not meaningful as a primer's. */
export const TM_MIN_LENGTH = 10;

const R = 1.987;

/** dH (kcal/mol) and dS (cal/(K x mol)) of each dinucleotide step, 5' to 3', SantaLucia 1998 Table 1. */
const STEP = /** @type {Record<string, [number, number]>} */ ({
  AA: [-7.9, -22.2],
  TT: [-7.9, -22.2],
  AT: [-7.2, -20.4],
  TA: [-7.2, -21.3],
  CA: [-8.5, -22.7],
  TG: [-8.5, -22.7],
  GT: [-8.4, -22.4],
  AC: [-8.4, -22.4],
  CT: [-7.8, -21.0],
  AG: [-7.8, -21.0],
  GA: [-8.2, -22.2],
  TC: [-8.2, -22.2],
  CG: [-10.6, -27.2],
  GC: [-9.8, -24.4],
  GG: [-8.0, -19.9],
  CC: [-8.0, -19.9],
});
/** Initiation at a terminal G-C pair and at a terminal A-T pair, added once per end. */
const INIT_GC = /** @type {[number, number]} */ ([0.1, -2.8]);
const INIT_AT = /** @type {[number, number]} */ ([2.3, 4.1]);
/** The symmetry correction for a self-complementary sequence (entropy only). */
const SYMMETRY_DS = -1.4;

const COMPLEMENT = /** @type {Record<string, string>} */ ({ A: "T", C: "G", G: "C", T: "A" });

/** @param {string} sequence */
function reverseComplement(sequence) {
  return [...sequence].reverse().map((base) => COMPLEMENT[base]).join("");
}

/**
 * The Tm in degrees Celsius, unrounded, or null when the sequence is not an unambiguous DNA oligo of at least
 * TM_MIN_LENGTH bases.
 *
 * @param {string} sequence 5' to 3', upper case
 * @returns {number | null}
 */
export function primerTm(sequence) {
  if (!/^[ACGT]+$/.test(sequence) || sequence.length < TM_MIN_LENGTH) return null;
  let dH = 0;
  let dS = 0;
  for (let i = 0; i < sequence.length - 1; i += 1) {
    const [h, s] = /** @type {[number, number]} */ (STEP[sequence.slice(i, i + 2)]);
    dH += h;
    dS += s;
  }
  for (const end of [sequence[0], sequence[sequence.length - 1]]) {
    const [h, s] = end === "G" || end === "C" ? INIT_GC : INIT_AT;
    dH += h;
    dS += s;
  }
  const selfComplementary = sequence === reverseComplement(sequence);
  if (selfComplementary) dS += SYMMETRY_DS;
  // The salt correction of SantaLucia (1998) eq. 8, applied to the entropy: 0.368 per phosphate (N - 1) x ln [Na+].
  dS += 0.368 * (sequence.length - 1) * Math.log(TM_CONDITIONS.sodiumMM / 1000);
  const concentration = TM_CONDITIONS.primerNM * 1e-9;
  return (1000 * dH) / (dS + R * Math.log(concentration)) - 273.15;
}

/** The Tm to one decimal, or null where there is none. @param {string} sequence */
export function primerTmRounded(sequence) {
  const tm = primerTm(sequence);
  return tm === null ? null : Math.round(tm * 10) / 10;
}

/** NEB’s Tm calculator, which gives the annealing temperature for a particular polymerase. */
export const NEB_TM_CALCULATOR = Object.freeze({ url: "https://tmcalculator.neb.com/", name: "NEB Tm Calculator" });

/**
 * The sentence every page that shows a Tm carries: what the number is (an estimate, for comparing primers), what was
 * computed and under what conditions, from the one set of constants, so no page restates a number it could be wrong about.
 * It never calls the figure an annealing temperature; `annealingSentence` says where that comes from.
 */
export function tmStatement() {
  const { sodiumMM, primerNM, method, citation } = TM_CONDITIONS;
  return (
    `The melting temperature (Tm) is an estimate for comparing primers with each other, computed from the sequence with the ${method} ` +
    `(${citation}) at ${sodiumMM} mM monovalent cation and ${primerNM / 1000} µM primer. These are standard reporting ` +
    `conditions, not those of any one reaction buffer. A sequence with an ambiguity code has no single Tm and shows none.`
  );
}

/** Where the annealing temperature comes from: not from the Tm above. Plain text, with the calculator named. */
export function annealingSentence() {
  return `The Tm estimate is not an annealing temperature. For the annealing temperature of a particular polymerase, use the ${NEB_TM_CALCULATOR.name} (${NEB_TM_CALCULATOR.url}).`;
}

