// The one place a content kind and its slug become a site-api content id and back. site-api's ContentId
// is `^[A-Za-z0-9][A-Za-z0-9._-]{0,199}$` (no colon), so the separator is a dot. Pure, so the publication
// validator can share the length rule with the registry (content-kinds.server.ts).

/** The contract's ContentId allows at most 200 characters (site-api contract.ts). */
const CONTENT_ID_MAX = 200;

/** The kind that keeps a bare slug for its id, so every id posts already had is unchanged. */
export const DEFAULT_KIND = "post";

/** The separator between a kind and a slug. A bare id has none; a slug may itself contain it. */
const SEPARATOR = ".";

/**
 * The contract id for a kind's slug: posts keep the bare slug, every other kind is `<kind>.<slug>`.
 *
 * @param {string} kind
 * @param {string} slug
 */
export function encodeContentId(kind, slug) {
  return kind === DEFAULT_KIND ? slug : `${kind}${SEPARATOR}${slug}`;
}

/**
 * The kind and slug of a contract id. A post slug never contains the separator (SLUG_PATTERN), so an id
 * with none is a post; otherwise the kind is everything before the FIRST separator and the slug is the rest.
 *
 * @param {string} id
 * @returns {{ kind: string, slug: string }}
 */
export function decodeContentId(id) {
  const at = id.indexOf(SEPARATOR);
  if (at === -1) return { kind: DEFAULT_KIND, slug: id };
  return { kind: id.slice(0, at), slug: id.slice(at + 1) };
}

/**
 * Whether `<kind>.<slug>` fits the contract's id length, for a validator to refuse a slug that cannot.
 *
 * @param {string} kind
 * @param {string} slug
 */
export function contentIdFits(kind, slug) {
  return encodeContentId(kind, slug).length <= CONTENT_ID_MAX;
}

app/lib/content-pages.mjs.source:
/**
 * The Research, Teaching and Software pages: markdown in content/pages/, rendered at build time into
 * content/generated/pages.json like the About page, and served by one route module. This list is the
 * one place their paths are named: app/routes.ts registers a route per entry, the sitemap lists each,
 * and the build refuses a markdown file whose path is not here or an entry with no file.
 *
 * The 2026-09-27 cutover wrote them from the old WordPress site, its knowledge base and the lab's
 * notebooks (cutover.md, "Pages to build before the switch").
 */

import { ogImageKey } from "./content/og-card-text.mjs";
import { dictionaryEntryMarkdown, dictionaryEntryText } from "./dictionary-entries.mjs";
import { longDateUTC } from "./long-date.mjs";
import { splitSections } from "./search/records.mjs";

export const CONTENT_PAGE_PATHS = /** @type {const} */ ([
  "/research",
  "/research/retroviruses",
  "/research/retroviruses/human",
  "/research/retroviruses/avian",
  "/research/bacteriophages",
  "/research/science-education",
  "/research/phages",
  // Not in cutover.md's page list, but its redirect rows land old knowledge-base addresses here.
  "/research/protocols",
  // The protocols themselves are procedures (content/procedures/, docs/PROCEDURES.md), drawn from D1.
  // The phage lab calculators (job_c2b88d76b3c1). Their addresses are fixed: the citable version
  // (Zenodo DOI, JMBE) replaces them in place, so none of these may move.
  "/research/tools",
  "/research/tools/titer",
  "/research/tools/dilution",
  "/research/tools/webbed-plate",
  "/research/tools/moi",
  "/research/tools/eop",
  "/research/tools/lysate-volume",
  "/teaching",
  "/teaching/phage-discovery",
  "/teaching/virus-isolation",
  "/teaching/virus-isolation/faq",
  "/teaching/phage-bioinformatics",
  "/teaching/central-dogma",
  "/teaching/study-skills",
  "/software",
  "/software/foxhound",
  "/software/foxing",
  "/software/foxing-edu",
  "/software/germomics",
  "/software/capsid",
  "/software/enarratio",
  "/software/carrel",
  "/software/capsomer",
  // The CV. Its entries are the files in content/cv/ (docs/CV.md), not a markdown page kept in content/pages/.
  "/cv",
  // The legal pages, in Carrel with the rest (job_044f96426efa). /terms is also the terms the site's data is
  // published under: the `license` of every Dataset (app/lib/license.mjs).
  "/privacy",
  "/terms",
  // The accessibility statement (job_fea2f94832b3): what the gates check, in Carrel with the legal pages but
  // not one of them. It ships as a draft until Dustin approves its text, and the footer links it once published.
  "/accessibility",
]);

/**
 * The legal pages: the only ones whose front matter may state a `banner` (the one word "Draft") and a
 * `last_updated` date, which the layout draws for every reader and the markdown twin repeats. Carrel writes
 * both (carrel design-legal-pages.md).
 *
 * @type {readonly string[]}
 */
export const LEGAL_PAGE_PATHS = ["/privacy", "/terms"];

/** The one word a legal page's `banner` may say. */
export const LEGAL_BANNER = "Draft";

/**
 * The listed pages whose markdown is GENERATED from structured data rather than read from
 * content/pages/: build:content renders it from app/lib/cv/markdown.mjs, so the twin, sitemap, search
 * records and llms.txt treat /cv like every other page. Their HTML comes from their own route
 * (app/routes/cv.tsx) and their twin from another (app/routes/cv[.md].ts), both drawn from the cv table, so
 * pages.json and the pages table leave them out.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_FROM_DATA = ["/cv"];

/**
 * The listed pages a reader can open: every one whose page is published, and the ones generated from data.
 * llms.txt must list each of these. `published` is the published paths from whichever source the caller
 * judges against: the page files (readPublishedPages()) in CI and the gates, the D1 rows in the llms.txt save.
 *
 * @param {readonly string[]} published
 * @returns {string[]}
 */
export function publishedContentPagePaths(published) {
  return CONTENT_PAGE_PATHS.filter((path) => CONTENT_PAGES_FROM_DATA.includes(path) || published.includes(path));
}

/**
 * The listed pages that are drafts: llms.txt may name them (so a page's line can land before or after it is
 * published, in either order) but need not.
 *
 * @param {readonly string[]} published as for publishedContentPagePaths
 * @returns {string[]}
 */
export function draftContentPagePaths(published) {
  const open = publishedContentPagePaths(published);
  return CONTENT_PAGE_PATHS.filter((path) => !open.includes(path));
}

/**
 * The pages that have a file in content/pages/, a row in the pages table and the page save, but whose
 * route, layout and structured data are their own (app/routes/about.tsx, a ProfilePage with its photo). They
 * are not in CONTENT_PAGE_PATHS, so the research splat, a markdown twin, a search record and the llms.txt
 * rules never see them: moving About onto D1 changed where its prose is kept and nothing a visitor reads.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_OWN_ROUTE = ["/about"];

/** Every path a file in content/pages/ may name: the listed pages and the ones with a route of their own. */
export const PAGE_FILE_PATHS = /** @type {readonly string[]} */ ([...CONTENT_PAGE_PATHS, ...CONTENT_PAGES_OWN_ROUTE]);

/**
 * The headings on these pages that the header menus link to by anchor, as `path#id`. A menu shows a
 * section link only once it is listed here, and the build refuses an entry whose page has no heading
 * with that id, so no menu link lands on the top of a page for want of its heading.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGE_SECTIONS = ["/teaching#join-the-lab", "/teaching#teaching-philosophy"];

/**
 * The markdown file a path is written in: slashes to hyphens, `/research/phages` in research-phages.md.
 *
 * @param {string} path
 */
export function contentPageFile(path) {
  return `${path.slice(1).replaceAll("/", "-")}.md`;
}

/**
 * The markdown twin's URL: the page path plus `.md`. Not `contentPageFile`, which is the repo filename.
 *
 * @param {string} path
 */
export function contentPageMarkdownPath(path) {
  return `${path}.md`;
}

/**
 * The twin a machine reads. The HTML page's h1 is not in the source body, so the title is the first line,
 * followed by the page's dictionary entry where it has one, where the page shows it. The entry is the
 * caller's to give: the build reads it from content/dictionary, the Worker from D1 (docs/DICTIONARY.md).
 *
 * @param {{ path?: string, title: string, markdown: string, banner?: string, lastUpdated?: string }} page
 * @param {import("./dictionary-entries.mjs").DictionaryEntry} [entry] the page's published entry, if any
 */
export function contentPageMarkdownBody(page, entry) {
  const body = String(page.markdown ?? "").replace(/^\n+/, "");
  const lead = entry ? `${dictionaryEntryMarkdown(entry)}\n` : "";
  // A legal page's banner and date are facts a reader sees under the title, so the twin states them too.
  const stated = [page.banner, page.lastUpdated ? `Last updated: ${longDateUTC(page.lastUpdated)}` : ""].filter(Boolean);
  const legal = stated.length > 0 ? `${stated.join("\n\n")}\n\n` : "";
  return `# ${page.title}\n\n${legal}${lead}${body}`;
}

/**
 * The pages build:og draws a social card of their own, by the root they sit under: the root and every
 * page below it, so a calculator added under /research/tools is carded with no edit here. Every other
 * page keeps the site card. Adding a root cards its pages on the next build:og.
 *
 * @type {readonly string[]}
 */
export const CARDED_PAGE_ROOTS = ["/software", "/research/tools", "/cv"];

/** @param {string} path */
export function hasPageCard(path) {
  return CARDED_PAGE_ROOTS.some((root) => path === root || path.startsWith(`${root}/`));
}

/**
 * What build:og draws for a page, in the shape ogImageKey hashes: the page's og:title (its SERP title)
 * and its description, with no date line, since these pages are not dated. The `page-` prefix keeps a
 * page's key apart from a post's, and build:og refuses two cards with one key.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 */
export function contentPageCardInput(page) {
  return {
    slug: `page-${page.path.slice(1).replaceAll("/", "-")}`,
    title: page.seoTitle,
    description: page.description,
    publishAt: null,
  };
}

/**
 * The /media path of a page's card, which its og:image names, or null for a page on the site card. The
 * key hashes what the card draws, so a retitled page names a new card, which build:og then draws.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 * @returns {string | null}
 */
export function contentPageCardPath(page) {
  return hasPageCard(page.path) ? `/media/${ogImageKey(contentPageCardInput(page))}` : null;
}

/**
 * What a Dataset node says about a page's first markdown table, read from the markdown the page renders:
 * its column headings, as the variables, and the span of its Year column, as an ISO 8601 interval. Null
 * when the page has no table.
 *
 * @param {string} markdown
 * @returns {{ variableMeasured: string[], temporalCoverage: string | null, rows: number } | null}
 */
export function markdownTableFacts(markdown) {
  const lines = String(markdown ?? "").split("\n");
  const rule = /^\|(\s*:?-+:?\s*\|)+\s*$/;
  const at = lines.findIndex((line, i) => /^\|.*\|\s*$/.test(line) && rule.test(lines[i + 1] ?? ""));
  if (at < 0) return null;
  const cells = (/** @type {string} */ line) =>
    line
      .trim()
      .replace(/^\||\|$/g, "")
      .split("|")
      .map((cell) => cell.trim());
  const headings = cells(lines[at] ?? "");
  /** @type {string[][]} */
  const rows = [];
  for (let i = at + 2; i < lines.length && (lines[i] ?? "").startsWith("|"); i += 1) rows.push(cells(lines[i] ?? ""));
  const yearColumn = headings.findIndex((heading) => /^year$/i.test(heading));
  const years =
    yearColumn < 0
      ? []
      : rows.map((row) => Number(row[yearColumn])).filter((year) => Number.isInteger(year) && year > 0);
  const first = Math.min(...years);
  const last = Math.max(...years);
  const temporalCoverage = years.length === 0 ? null : first === last ? String(first) : `${first}/${last}`;
  return { variableMeasured: headings, temporalCoverage, rows: rows.length };
}

/** Google clips near these; the build refuses longer ones rather than ship a clipped result. */
export const SEO_TITLE_MAX = 60;
export const DESCRIPTION_MAX = 155;

/** The hubs, and the trail label each gives the pages under it. */
const HUBS = /** @type {const} */ ([
  ["/research", "Research"],
  ["/teaching", "Teaching"],
  ["/software", "Software"],
]);

/**
 * The trail above a page: its hub, the page it sits under when it is three deep (the course above its
 * FAQ), then the page itself. A hub stands alone.
 *
 * @param {{ path: string, title: string }} page
 * @param {(path: string) => string | undefined} [titleOf] the title of another listed page
 * @returns {Array<[string, string]>}
 */
export function contentPageTrail(page, titleOf = () => undefined) {
  const hub = HUBS.find(([path]) => page.path.startsWith(`${path}/`));
  if (!hub) return [[page.title, page.path]];
  const trail = /** @type {Array<[string, string]>} */ ([[hub[1], hub[0]]]);
  const parent = page.path.slice(0, page.path.lastIndexOf("/"));
  const parentTitle = parent !== hub[0] ? titleOf(parent) : undefined;
  if (parentTitle) trail.push([parentTitle, parent]);
  trail.push([page.title, page.path]);
  return trail;
}

/** The search uid of a page path: a removal needs it to find the page's records. */
export function contentPageSearchUid(/** @type {string} */ path) {
  return `page:${path.slice(1).replaceAll("/", ":")}`;
}

/**
 * Search inputs in the shape `recordsForPages` takes: one record for the page, one per heading, each
 * deep-linking to the heading's own anchor.
 *
 * @param {Array<{ path: string, title: string, description: string, markdown: string, toc: Array<{ depth: number, id: string, text: string }> }>} pages
 * @param {(path: string) => import("./dictionary-entries.mjs").DictionaryEntry | undefined} [entryFor] the
 *   published dictionary entry of a page path, which leads that page's record
 */
export function contentPageSearchInputs(pages, entryFor = () => undefined) {
  return pages.map((page) => {
    const { intro, sections } = splitSections(page.markdown, page.toc);
    const entry = entryFor(page.path);
    return {
      url: page.path,
      uid: contentPageSearchUid(page.path),
      title: page.title,
      description: page.description,
      intro: entry ? `${dictionaryEntryText(entry)} ${intro}` : intro,
      sections: sections.map(({ anchor, title, body }) => ({ anchor, title, body })),
    };
  });
}

app/lib/cv/validate.mjs.source:
// The one validation module for the CV (docs/CV.md). CI (build:content, test/cv.test.mjs), sync:content and the
// CV save all call it, so a file CI passes is the file a save accepts. It holds a file to its shape, to the
// privacy rules, to the house style (no wide dash) and, once the files are joined to the publications, to the
// rules that need the whole CV: a cited paper exists and lists Dustin, and each section reads newest first.
// Pure: no Env, no filesystem, no clock beyond the year bound below.

import matter from "gray-matter";

import { findWideDashes } from "../content/wide-dash.mjs";
import { canonicalAuthor } from "../publications/authors.mjs";
import { AREAS, ROLES } from "./view.mjs";

const AREA_IDS = new Set(AREAS.map(([id]) => /** @type {string} */ (id)));
const ROLE_IDS = new Set(ROLES.map(([id]) => /** @type {string} */ (id)));

/** The owner, whom every paper the CV claims must list (as the CV's role for it is read from the author list). */
const OWNER = "Dustin Edwards";

/** The edition stamp the CV prints: a season and a year, as "Fall 2026". */
const EDITION_PATTERN = /^(Spring|Summer|Fall|Winter) (\d{4})$/;

/** Entries are dated between these years, so a typo such as 2205 is refused rather than charted. */
const YEAR_MIN = 1950;
const YEAR_MAX = 2100;

const DOI_PATTERN = /^10\.\d{4,9}\/\S+$/;
const HTTPS = /^https:\/\/\S+$/;

/** The sections an appointment or a service line sits under, in the order the CV prints them. */
const APPOINTMENT_SECTIONS = ["Positions", "Administrative and leadership"];
const SERVICE_SECTIONS = [
  "Department",
  "College",
  "University",
  "Professional",
  "Community",
  "Compensated professional consulting",
  "Professional memberships",
];

/**
 * What no CV line may carry (the privacy rules): an email, a phone number, a room, a private community group.
 * Read from the values, so a comment explaining the rule cannot trip it.
 */
const PRIVACY = /** @type {const} */ ([
  [/@[a-z0-9-]+\.[a-z]{2,}/i, "an email address"],
  [/\(\d{3}\)\s*\d{3}-\d{4}|\b\d{3}-\d{3}-\d{4}\b/, "a phone number"],
  [/\bRoom\b|\bSuite\b|\bOffice \d/i, "a room"],
  [/Mountains Lake/i, "a private community group"],
]);

/**
 * A field's kind, for one entry type: `s` a non-empty string, `n` a non-negative integer, `money` US dollars to the cent, `b` a boolean, and
 * a trailing `?` makes it optional. The shared fields (year, endYear, areas, role, links) are checked apart.
 */
const SHAPES = /** @type {const} */ ({
  appointment: { section: "s", title: "s", org: "s", detail: "s?", duties: "duties?", headline: "b?" },
  education: { title: "s", org: "s", detail: "s?" },
  grant: { amount: "money", title: "s", funder: "s?", note: "s?" },
  award: { title: "s", org: "s?", place: "s?" },
  talk: { title: "s", presenters: "strings", venue: "s" },
  course: { code: "s", title: "s", org: "s", term: "s" },
  mentoring: { section: "s", count: "n", unit: "unit", level: "s", program: "s", org: "s", detail: "s?", cohort: "b" },
  service: { section: "s", title: "s", org: "s?", place: "s?" },
  development: { title: "s", org: "s?", place: "s?" },
});

/** The inline paper (one the site has no record for) states its own citation. */
const INLINE_PAPER = /** @type {const} */ ({
  title: "s",
  authors: "strings",
  journal: "s",
  volume: "s?",
  issue: "s?",
  pages: "s?",
});

const SHARED_KEYS = ["year", "endYear", "areas", "role", "links"];

/** @param {unknown} value @returns {value is Record<string, unknown>} */
const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

/** @param {unknown} value */
const isText = (value) => typeof value === "string" && value.length > 0 && value === value.trim();

/** @param {unknown} value @returns {value is number} */
const isCount = (value) => typeof value === "number" && Number.isInteger(value) && value >= 0;

/**
 * @param {unknown} value
 * @param {string} kind
 * @returns {string | null} a reason, or null when the value fits
 */
function misfit(value, kind) {
  const optional = kind.endsWith("?");
  const base = optional ? kind.slice(0, -1) : kind;
  if (value === undefined) return optional ? null : "is missing";
  switch (base) {
    case "s":
      return isText(value) ? null : "must be non-empty text with no space at either end";
    case "n":
      return isCount(value) ? null : "must be a whole number, zero or more";
    case "money":
      return typeof value === "number" && Number.isFinite(value) && value >= 0 && Math.round(value * 100) === value * 100
        ? null
        : "must be dollars, zero or more, to the cent";
    case "b":
      return typeof value === "boolean" ? null : "must be true or false";
    case "strings":
      return Array.isArray(value) && value.length > 0 && value.every(isText) ? null : "must be a non-empty list of text";
    case "unit":
      return value === "students" || value === "awards" ? null : 'must be "students" or "awards"';
    case "duties":
      return Array.isArray(value) &&
        value.length > 0 &&
        value.every(
          (duty) =>
            isRecord(duty) &&
            Object.keys(duty).every((key) => key === "heading" || key === "items") &&
            isText(duty.heading) &&
            Array.isArray(duty.items) &&
            duty.items.length > 0 &&
            duty.items.every(isText),
        )
        ? null
        : "must be a non-empty list of { heading, items } with items a non-empty list of text";
    default:
      throw new Error(`cv validate: unknown field kind ${kind}`);
  }
}

/**
 * @param {Record<string, unknown>} entry
 * @param {Record<string, string>} shape
 * @param {string} where
 * @param {string[]} errors
 */
function checkShape(entry, shape, where, errors) {
  for (const [key, kind] of Object.entries(shape)) {
    const reason = misfit(entry[key], kind);
    if (reason) errors.push(`${where}: ${key} ${reason}`);
  }
}

/**
 * The fields every dated entry carries, and the keys it may not.
 *
 * @param {Record<string, unknown>} entry
 * @param {string} where
 * @param {string[]} errors
 */
function checkShared(entry, where, errors) {
  const { year, endYear, areas, role, links } = entry;
  const yearOk = year === null || (typeof year === "number" && Number.isInteger(year) && year >= YEAR_MIN && year <= YEAR_MAX);
  if (!yearOk) errors.push(`${where}: year must be a whole year from ${YEAR_MIN} to ${YEAR_MAX}, or null for an undated line`);
  if (endYear !== undefined) {
    if (year === null) errors.push(`${where}: an undated line (year: null) has no endYear`);
    else if (endYear !== "present" && !(typeof endYear === "number" && Number.isInteger(endYear) && endYear <= YEAR_MAX)) {
      errors.push(`${where}: endYear must be a whole year or "present"`);
    } else if (typeof endYear === "number" && typeof year === "number" && endYear < year) {
      errors.push(`${where}: endYear ${endYear} is before year ${year}`);
    }
  }
  if (!Array.isArray(areas) || !areas.every((a) => typeof a === "string" && AREA_IDS.has(a))) {
    errors.push(`${where}: areas must be a list (empty is allowed) of ${[...AREA_IDS].join(", ")}`);
  } else if (new Set(areas).size !== areas.length) {
    errors.push(`${where}: areas names one area twice`);
  }
  if (role !== null && !(typeof role === "string" && ROLE_IDS.has(role))) {
    errors.push(`${where}: role must be null or one of ${[...ROLE_IDS].join(", ")}`);
  }
  if (links !== undefined) {
    const linksOk =
      Array.isArray(links) &&
      links.length > 0 &&
      links.every((l) => isRecord(l) && Object.keys(l).length === 2 && isText(l.label) && typeof l.href === "string" && HTTPS.test(l.href));
    if (!linksOk) errors.push(`${where}: links must be a non-empty list of { label, href } with an https href`);
  }
}

/**
 * One entry of a section file, held to its type's shape.
 *
 * @param {import("./types.ts").CvType} type
 * @param {unknown} entry
 * @param {string} where
 * @param {string[]} errors
 */
function checkEntry(type, entry, where, errors) {
  if (!isRecord(entry)) {
    errors.push(`${where}: an entry is a mapping of fields`);
    return;
  }
  if ("type" in entry) errors.push(`${where}: an entry does not state its type; the file's front matter does`);

  if (type === "publication" && "doi" in entry) {
    for (const key of Object.keys(entry)) {
      if (key !== "doi") {
        errors.push(`${where}: a paper named by DOI states nothing else (${key}); its facts come from content/publications/`);
      }
    }
    if (typeof entry.doi !== "string" || !DOI_PATTERN.test(entry.doi)) errors.push(`${where}: doi is not a DOI`);
    return;
  }

  /** @type {Record<string, string>} */
  const shape = type === "publication" ? INLINE_PAPER : SHAPES[/** @type {Exclude<typeof type, "publication">} */ (type)];
  checkShape(entry, shape, where, errors);
  checkShared(entry, where, errors);
  const known = new Set([...Object.keys(shape), ...SHARED_KEYS]);
  for (const key of Object.keys(entry)) {
    if (!known.has(key)) errors.push(`${where}: "${key}" is not a field of a ${type} entry`);
  }
  if (type === "appointment" && !APPOINTMENT_SECTIONS.includes(/** @type {string} */ (entry.section))) {
    errors.push(`${where}: section must be one of ${APPOINTMENT_SECTIONS.join(", ")}`);
  }
  if (type === "service" && !SERVICE_SECTIONS.includes(/** @type {string} */ (entry.section))) {
    errors.push(`${where}: section must be one of ${SERVICE_SECTIONS.join(", ")}`);
  }
}

/**
 * The profile: the edition stamp, the person and the presentation totals.
 *
 * @param {Record<string, unknown>} data
 * @param {string[]} errors
 */
function checkProfile(data, errors) {
  const { edition, person, presentations } = data;
  for (const key of Object.keys(data)) {
    if (!["edition", "person", "presentations"].includes(key)) errors.push(`profile: "${key}" is not a field of the profile`);
  }
  if (typeof edition !== "string" || !EDITION_PATTERN.test(edition)) {
    errors.push('edition must be a season and a year, such as "Fall 2026"');
  }
  if (!isRecord(person)) {
    errors.push("person must be a mapping of name, degree, discipline, department and org");
  } else {
    for (const key of ["name", "degree", "discipline", "department", "org"]) {
      if (!isText(person[key])) errors.push(`person.${key} must be non-empty text with no space at either end`);
    }
    for (const key of Object.keys(person)) {
      if (!["name", "degree", "discipline", "department", "org"].includes(key)) {
        errors.push(
          key === "title"
            ? 'person.title is not a field of the person: the title is derived from the current appointment and the discipline (app/lib/identity.mjs)'
            : `person.${key} is not a field of the person`,
        );
      }
    }
    if (person.name !== OWNER) errors.push(`person.name is "${String(person.name)}", the site's one name for him is "${OWNER}"`);
  }
  if (!isRecord(presentations)) {
    errors.push("presentations must be a mapping of international, national, from and to");
  } else {
    for (const key of ["international", "national"]) {
      if (!isCount(presentations[key])) errors.push(`presentations.${key} must be a whole number, zero or more`);
    }
    for (const key of ["from", "to"]) {
      const value = presentations[key];
      if (!(typeof value === "number" && Number.isInteger(value) && value >= YEAR_MIN && value <= YEAR_MAX)) {
        errors.push(`presentations.${key} must be a whole year from ${YEAR_MIN} to ${YEAR_MAX}`);
      }
    }
    for (const key of Object.keys(presentations)) {
      if (!["international", "national", "from", "to"].includes(key)) errors.push(`presentations.${key} is not a field of the presentations`);
    }
    if (typeof presentations.from === "number" && typeof presentations.to === "number" && presentations.from > presentations.to) {
      errors.push("presentations.from is after presentations.to");
    }
  }
}

/**
 * Parses and judges one CV file.
 *
 * @param {{ slug: string, type: import("./types.ts").CvType | "profile" }} file the registry's entry for it
 * @param {string} raw the whole file, front matter included
 * @returns {{ ok: false, errors: string[] } | { ok: true, errors: [], record: import("./types.ts").CvFileRecord }}
 */
export function parseCvFile(file, raw) {
  /** @type {string[]} */
  const errors = [];
  for (const hit of findWideDashes(raw)) {
    errors.push(`line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`);
  }
  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return { ok: false, errors: [...errors, `the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`] };
  }
  const data = /** @type {Record<string, unknown>} */ (parsed.data);
  if (parsed.content.trim() !== "") errors.push("the file has text after its front matter, which no page shows; the CV is the front matter alone");

  const { slug, type } = file;
  if (type === "profile") {
    checkProfile(data, errors);
  } else {
    for (const key of Object.keys(data)) {
      if (key !== "type" && key !== "entries") errors.push(`"${key}" is not a field of a section file (type, entries)`);
    }
    if (data.type !== type) errors.push(`type is ${JSON.stringify(data.type)}, but ${slug} holds ${type} entries`);
    if (!Array.isArray(data.entries) || data.entries.length === 0) {
      errors.push("entries must be a non-empty list");
    } else {
      data.entries.forEach((entry, i) => checkEntry(type, entry, `entries[${i}]`, errors));
    }
  }

  // The privacy rules read the values, not the comments: JSON of what the file states.
  const values = JSON.stringify(data);
  for (const [pattern, what] of PRIVACY) {
    if (pattern.test(values)) errors.push(`the file carries ${what}; the CV never does`);
  }
  if (errors.length > 0) return { ok: false, errors };

  /** @type {import("./types.ts").CvFileRecord} */
  const record =
    type === "profile"
      ? {
          slug: "profile",
          type: "profile",
          edition: /** @type {string} */ (data.edition),
          person: /** @type {import("./types.ts").CvPerson} */ (data.person),
          presentations: /** @type {import("./types.ts").CvPresentations} */ (data.presentations),
        }
      : {
          slug,
          type,
          // The file states the type once; each entry carries it from here on.
          entries: /** @type {Array<Record<string, unknown>>} */ (data.entries).map(
            (e) => /** @type {import("./types.ts").CvSourceEntry} */ ({ type, ...e }),
          ),
        };
  return { ok: true, errors: [], record };
}

/**
 * The paper references against the publication records: each DOI exists as a published paper, appears once,
 * and the paper lists the owner among its authors (the CV cannot claim a paper he did not write).
 *
 * @param {import("./types.ts").CvSourceEntry[]} entries
 * @param {Map<string, import("../publications/types.ts").Publication>} byDoi the published records by lower-cased DOI
 * @returns {string[]}
 */
export function paperRefErrors(entries, byDoi) {
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  for (const entry of entries) {
    if (entry.type !== "publication" || !("doi" in entry)) continue;
    const key = entry.doi.toLowerCase();
    if (seen.has(key)) errors.push(`DOI ${entry.doi} is listed twice`);
    seen.add(key);
    const paper = byDoi.get(key);
    if (!paper) {
      errors.push(`no published publication has DOI ${entry.doi}; add its file to content/publications/ first, and publish it`);
    } else if (!paper.authors.some((name) => canonicalAuthor(name) === OWNER)) {
      errors.push(`DOI ${entry.doi} does not list ${OWNER} among its authors, so the CV cannot claim it`);
    }
  }
  return errors;
}

/**
 * The types whose sections read newest first, undated lines last, so the page, the twin and the PDF agree on
 * an order the twin states for grants. Service and mentoring lines keep the CV's own order within a section (a
 * committee is listed with its chair first, a cohort by program), so the rule does not reach them.
 */
const NEWEST_FIRST_TYPES = [
  "appointment",
  "education",
  "publication",
  "grant",
  "award",
  "talk",
  "course",
  "development",
];

/**
 * Judged on the resolved entries, so a paper's year is the record's.
 *
 * @param {Array<{ id: string, type: string, section: string | null, year: number | null }>} entries
 * @returns {string[]}
 */
export function orderErrors(entries) {
  /** @type {string[]} */
  const errors = [];
  /** @type {Map<string, { year: number | null, id: string }>} */
  const last = new Map();
  for (const e of entries) {
    if (!NEWEST_FIRST_TYPES.includes(e.type)) continue;
    const key = `${e.type}/${e.section ?? ""}`;
    const before = last.get(key);
    if (before) {
      if (before.year === null && e.year !== null) {
        errors.push(`${e.id} is dated ${e.year} but follows the undated ${before.id}; undated lines come last in their section`);
      } else if (before.year !== null && e.year !== null && e.year > before.year) {
        errors.push(`${e.id} (${e.year}) follows ${before.id} (${before.year}); each section reads newest first`);
      }
    }
    last.set(key, { year: e.year, id: e.id });
  }
  return errors;
}

