// The form branch is selected ONLY by `intent=upload-form`, never by sniffing a header: a changed
// default header would silently hand the editors' `response.json()` an HTML page.
// Must stay loadable by node:test: never import anything reaching a binding, a `.server` module or React.

import { byteSize } from "./byte-size.mjs";

export const ALLOWED = new Map([
  ["image/webp", "webp"],
  ["image/png", "png"],
  ["image/jpeg", "jpg"],
  ["image/avif", "avif"],
  ["image/gif", "gif"],
  // Stored as JPEG (site-api's prepareUpload converts them), so the extension is never used.
  ["image/heic", "jpg"],
  ["image/heif", "jpg"],
]);

// NOT IN THE ALLOWLIST, and refused by name rather than as an unknown type: an SVG can carry script,
// and /media is this site's own origin. The /media CSP (workers/csp.mjs) is the second wall, for
// anything that reaches the bucket some other way.
const SVG_TYPE = "image/svg+xml";

const SVG_REFUSED =
  "SVG is not accepted: it can carry script, and /media is this site's own origin. " +
  "Export it as PNG or WebP.";

// A hint, not a control: drag-drop or a scripted post ignores `accept`. The control is the server check.
export const ACCEPT_ATTRIBUTE = [...ALLOWED.keys()].join(",");

export const MAX_BYTES = 10 * 1024 * 1024;

export const UPLOAD_FORM_INTENT = "upload-form";

export const UPLOAD_RETURN_PATH = "/admin/media";

/**
 * @param {unknown} intent the submitted `intent` field, whatever arrived
 * @returns {boolean}
 */
export function isFormUpload(intent) {
  return intent === UPLOAD_FORM_INTENT;
}

/**
 * Both editors destructure `url`, and one inserts it into the markdown: a rename breaks inserts with no
 * type error.
 *
 * @param {string} key
 */
export function uploadSuccessBody(key) {
  return { url: `/media/${key}`, key };
}

/**
 * @param {string} message
 */
export function uploadErrorBody(message) {
  return { error: message };
}


// A code in the URL, not the message, so the address bar never carries prose someone can edit.
const UPLOAD_ERRORS = {
  "no-file": "No file was chosen.",
  "unsupported-type":
    `That file type is not one this endpoint accepts. Uploads here are images: ` +
    `${[...ALLOWED.keys()].map((mime) => mime.split("/")[1]).join(", ")}.`,
  "too-large": `That image is over the ${MAX_BYTES / (1024 * 1024)} MB limit.`,
  "svg-refused": SVG_REFUSED,
  "content-mismatch":
    "That file's bytes are not the image type it was uploaded as. " +
    "Export the image again as PNG, JPEG or WebP.",
  "images-unavailable":
    "The image could not be measured, because Cloudflare Images did not answer. " +
    "Nothing was stored; try again.",
};

/**
 * `no-file` is left to each caller, because its repair differs. The byte signature is site-api's prepareUpload's,
 * after this: SVG bytes declared `image/png` fail it as `content-mismatch`.
 *
 * @param {{ type: string, bytes: { byteLength: number } }} file what arrived, before any store
 * @returns {{ code: "unsupported-type" | "svg-refused" | "too-large", message: string, status: number } | null}
 */
export function validateUpload({ type, bytes }) {
  const size = bytes.byteLength;

  // Before the generic check, so the refusal says why instead of reading as an oversight.
  if (type.toLowerCase().split(";")[0]?.trim() === SVG_TYPE) {
    return { code: "svg-refused", message: SVG_REFUSED, status: 415 };
  }

  if (!ALLOWED.has(type)) {
    return {
      code: "unsupported-type",
      message: `Unsupported image type "${type || "unknown"}".`,
      status: 415,
    };
  }

  if (size > MAX_BYTES) {
    return {
      code: "too-large",
      message: `Image is ${byteSize(size)}, over the ${MAX_BYTES / (1024 * 1024)} MB limit.`,
      status: 413,
    };
  }

  return null;
}

/**
 * @param {string | null} code
 * @returns {string | null} the sentence, or null for a code nothing emits
 */
export function uploadErrorSentence(code) {
  if (!code) return null;
  return Object.prototype.hasOwnProperty.call(UPLOAD_ERRORS, code)
    ? UPLOAD_ERRORS[/** @type {keyof typeof UPLOAD_ERRORS} */ (code)]
    : null;
}

/**
 * Success carries the key, so a reload repeats a harmless read rather than a second upload.
 *
 * @param {{ ok: true, key: string } | { ok: false, code: string }} result
 */
export function uploadRedirectTo(result) {
  const params = result.ok
    ? `uploaded=${encodeURIComponent(result.key)}`
    : `upload-error=${encodeURIComponent(result.code)}`;
  return `${UPLOAD_RETURN_PATH}?${params}`;
}

app/lib/operator/sync-report.mjs.source:
// `converged` is DERIVED from counts read back after the writes, never asserted by the caller: `ship`
// fails on it, and a loop over a wrongly built corpus still reports a healthy `uploaded`.

/**
 * Any failed key makes `converged` false, even when the counts happen to agree.
 *
 * @param {{
 *   uploaded: number,
 *   removed: number,
 *   cacheDropped: number,
 *   expected: number,
 *   present: number,
 *   failed?: Array<{ key: string, error: string }>,
 * }} counts
 * @returns {{
 *   uploaded: number,
 *   removed: number,
 *   cacheDropped: number,
 *   expected: number,
 *   present: number,
 *   drift: number,
 *   converged: boolean,
 *   failed: Array<{ key: string, error: string }>,
 *   unreadable: boolean,
 * }}
 */
export function askSyncReport(counts) {
  const agreement = convergence(counts.expected, counts.present);
  // An absent list means the caller had nothing to report; anything else that is not an array is an
  // unreadable failure list, and a report that cannot say what failed has not converged.
  const failedReadable = counts.failed === undefined || Array.isArray(counts.failed);
  const failed = Array.isArray(counts.failed) ? counts.failed : [];
  return {
    uploaded: whole(counts.uploaded),
    removed: whole(counts.removed),
    cacheDropped: whole(counts.cacheDropped),
    ...agreement,
    converged: agreement.converged && failedReadable && failed.length === 0,
    failed,
    unreadable: !failedReadable,
  };
}

/**
 * ABSOLUTE drift: an index holding more than its source is stale too, and a negative number would read
 * as healthy to a caller testing `drift > 0`.
 *
 *
 * @param {unknown} expectedRaw @param {unknown} presentRaw
 * @returns {{ expected: number, present: number, drift: number, converged: boolean }}
 */
function convergence(expectedRaw, presentRaw) {
  const expected = whole(expectedRaw);
  const present = whole(presentRaw);
  const drift = Math.abs(expected - present);
  return {
    expected,
    present,
    drift,
    converged: unreadable(expectedRaw, presentRaw) ? false : drift === 0,
  };
}

/**
 * Media drifts by KEY: dropping one file while inventing one row leaves the totals equal, so drift is
 * `missing` plus `extra`, not a count difference.
 *
 *
 * @param {{
 *   indexed: number,
 *   removed: number,
 *   failures: string[],
 *   expected: number,
 *   present: number,
 *   missing: string[],
 *   extra: string[],
 * }} counts
 */
export function mediaSyncReport(counts) {
  const totals = convergence(counts.expected, counts.present);
  const missing = list(counts.missing);
  const extra = list(counts.extra);
  const drift = missing.length + extra.length;
  const failures = list(counts.failures);
  // Fails closed: a list that is not an array of strings cannot say what is missing or what failed, so
  // the report does not converge on it.
  const readable = [counts.missing, counts.extra, counts.failures].every(stringList);

  return {
    indexed: whole(counts.indexed),
    removed: whole(counts.removed),
    expected: totals.expected,
    present: totals.present,
    drift,
    missing,
    extra,
    failures,
    // A failed derivation leaves no row and no source change, so the key sets can agree while wrong.
    converged: totals.converged && readable && drift === 0 && failures.length === 0,
    unreadable: !readable,
  };
}

/** @param {unknown} v @returns {string[]} */
function list(v) {
  return Array.isArray(v) ? v.filter((x) => typeof x === "string") : [];
}

/** @param {unknown} v @returns {boolean} */
function stringList(v) {
  return Array.isArray(v) && v.every((x) => typeof x === "string");
}

/**
 * @param {ReturnType<typeof mediaSyncReport>} report
 * @returns {string}
 */
export function mediaSyncSummary(report) {
  if (report.converged) {
    return (
      `Media index converged: ${report.expected} expected, ${report.present} present, ` +
      `${report.indexed} indexed, ${report.removed} removed.`
    );
  }
  const why = [
    report.missing.length ? `${report.missing.length} missing` : "",
    report.extra.length ? `${report.extra.length} extra` : "",
    report.failures.length ? `${report.failures.length} failed to derive` : "",
    report.unreadable ? "an unreadable missing, extra or failure list" : "",
  ].filter(Boolean);
  return (
    `MEDIA INDEX STILL DRIFTED: ${report.expected} expected, ${report.present} present` +
    (why.length ? ` (${why.join(", ")})` : "") +
    `, after indexing ${report.indexed} and removing ${report.removed}.`
  );
}

/**
 * An unreadable count is not a passing count.
 *
 * @param {unknown} a @param {unknown} b
 */
function unreadable(a, b) {
  return !Number.isInteger(a) || !Number.isInteger(b);
}

/** @param {unknown} n @returns {number} */
function whole(n) {
  return Number.isInteger(n) ? Number(n) : 0;
}

/**
 * @param {ReturnType<typeof askSyncReport>} report
 * @returns {string}
 */
export function askSyncSummary(report) {
  if (report.failed?.length) {
    return (
      `ASK UPLOAD FAILED for ${report.failed.length} key(s) after retries: ` +
      `${report.failed.map((f) => `${f.key} (${f.error})`).join(", ")}. ` +
      `${report.expected} expected, ${report.present} present.`
    );
  }
  if (report.unreadable) {
    return (
      `ASK SYNC REPORT UNREADABLE: the failure list was not a list, so what failed is unknown. ` +
      `${report.expected} expected, ${report.present} present.`
    );
  }
  return report.converged
    ? `Ask index converged: ${report.expected} expected, ${report.present} present, ` +
        `${report.uploaded} uploaded, ${report.removed} removed.`
    : `ASK INDEX STILL SHORT: ${report.expected} expected, ${report.present} present, ` +
        `drift ${report.drift}, after uploading ${report.uploaded} and removing ${report.removed}.`;
}

app/lib/podcast/clock.mjs.source:
// On its own, without the feed parser, because the player's enhancement bundle imports it.

/**
 * A duration as a clock: `m:ss`, or `h:mm:ss` from an hour. A missing or unreadable length (NaN,
 * which an audio element reports before its metadata loads) reads as 0:00.
 *
 * @param {number} seconds
 */
export function clockTime(seconds) {
  const s = Math.max(0, Math.floor(seconds || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const rest = String(s % 60).padStart(2, "0");
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${rest}` : `${m}:${rest}`;
}

app/lib/publications/listing.mjs.source:
/**
 * The publication index (docs/PUBLICATIONS.md): its fields declared once for Capsomer's catalog, so the search box, the
 * topic and other facets, the sort menu, the year headings and the counts all come from this one declaration. Pure
 * over the query string and the papers it is handed. The route adds the citation counts (a D1 read) and the page copy.
 *
 * What did not change, because search engines and the machine-readable gates hold it: `?topic=` is the address of a
 * topic's papers, and exactly the four bare single-topic addresses canonicalise to themselves (`soleTopic`); every other
 * address is a view of the base page.
 */

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { decodeEntities } from "./entities.mjs";
import { TOPICS, TOPIC_IDS } from "./topics.mjs";

/** @typedef {import("./types.ts").Publication} Publication */
/** @typedef {import("./types.ts").PublicationType} PublicationType */
/** @typedef {import("./types.ts").TopicId} TopicId */

/**
 * Conference abstracts stay in the data file, which the CV also reads, and are excluded here.
 *
 * @type {Set<PublicationType>}
 */
export const SHOWCASE_TYPES = new Set([
  "article",
  "review",
  "chapter",
  "teaching-resource",
]);

const PUBLICATIONS_BASE = "/research/publications";

const TYPE_LABELS = /** @type {Record<string, string>} */ ({
  article: "Article",
  review: "Review",
  chapter: "Chapter",
  "teaching-resource": "Teaching resource",
});

/** The journal, volume and pages as the page prints them, entities decoded (the year has its own column). @param {Publication} p */
export function venue(p) {
  return decodeEntities([p.journal, p.volume, p.pages].filter(Boolean).join(", "));
}

/** The papers' catalog. Newest first by default, under a heading for each year; any search or other sort is flat. */
export const PUBLICATIONS = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Publication>} */ ({
    id: "papers",
    noun: ["paper", "papers"],
    basePath: PUBLICATIONS_BASE,
    itemKey: (p) => p.id,
    defaultSort: "-year",
    group: { field: "year" },
    fields: [
      { key: "title", label: "Title", value: (p) => decodeEntities(p.title), search: 3, sort: true, column: { header: "Paper" } },
      { key: "authors", label: "Authors", value: (p) => p.authors.map(decodeEntities), search: 1 },
      { key: "journal", label: "Journal", value: (p) => venue(p), search: 2, column: { header: "Journal", drop: 1 } },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { labels: { asc: "oldest first", desc: "newest first" } },
        column: { header: "Year", align: "end", hideWhenGrouped: true },
      },
      {
        key: "topic",
        label: "Topic",
        value: (p) => p.topics,
        facet: { kind: "many", general: true, order: TOPICS.map((t) => t.id), label: (v) => TOPICS.find((t) => t.id === v)?.label ?? v },
      },
      { key: "type", label: "Type", value: (p) => p.type, facet: { kind: "many", label: (v) => TYPE_LABELS[v] ?? v } },
      // Chosen with `?selected=1`, as the page's "Selected" filter always was.
      { key: "selected", label: "Selected", value: (p) => (p.selected ? "1" : null), facet: { kind: "one", label: () => "Selected papers" } },
      { key: "access", label: "Access", value: (p) => (p.isOpenAccess ? "open" : null), facet: { kind: "one", label: () => "Open access" } },
    ],
  }),
);

/**
 * The address a request written in the old parameters should have, or null. The page used `?sort=year-desc|year-asc|title`
 * and `?selected=1|true`; the catalog says `sort=-year|year|title` and `selected=1`. A link in the wild keeps working: it
 * is sent, once, to the same view at its new address. A request with none of the old spellings is left alone.
 *
 * @param {URL} url
 */
export function legacyAddress(url) {
  const params = url.searchParams;
  const sort = params.get("sort");
  const oldSort = sort === "year-desc" || sort === "year-asc";
  const oldSelected = (params.get("selected") ?? "").toLowerCase() === "true";
  if (!oldSort && !oldSelected) return null;
  const next = new URLSearchParams(params);
  if (sort === "year-desc") next.delete("sort");
  if (sort === "year-asc") next.set("sort", "year");
  if (oldSelected) next.set("selected", "1");
  return queryCatalog(PUBLICATIONS, [], parseCatalogParams(PUBLICATIONS, next)).href();
}

/**
 * Only the four bare single-topic URLs self-canonical: the rest are subsets or orderings, and q is unbounded.
 *
 * @param {URLSearchParams} params
 * @returns {TopicId | null}
 */
export function soleTopic(params) {
  const topics = params.getAll("topic").filter((t) => TOPIC_IDS.has(t));
  const KNOWN_PARAMS = new Set(["topic", "q", "sort", "selected"]);
  const hasUnknownParam = [...params.keys()].some((k) => !KNOWN_PARAMS.has(k));
  return topics.length === 1 &&
    params.getAll("topic").length === 1 &&
    !params.has("q") &&
    !params.has("sort") &&
    !params.has("selected") &&
    !hasUnknownParam
    ? /** @type {TopicId} */ (topics[0])
    : null;
}

/**
 * The page's state for an address: the showcase papers run through the catalog, with the span the header states and the
 * canonical topic. Everything shown is in `result`.
 *
 * @param {URLSearchParams} params
 * @param {Publication[]} publications every published paper, newest first (app/db/publications.ts)
 */
export function publicationListing(params, publications) {
  const showcase = publications.filter((p) => SHOWCASE_TYPES.has(p.type));
  const result = queryCatalog(PUBLICATIONS, showcase, parseCatalogParams(PUBLICATIONS, params));
  const items = result.rows;
  const span = {
    papers: items.length,
    firstYear: items.length > 0 ? Math.min(...items.map((p) => p.year)) : null,
    lastYear: items.length > 0 ? Math.max(...items.map((p) => p.year)) : null,
    venues: new Set(items.map((p) => p.journal).filter(Boolean)).size,
  };
  return { items, result, span, soleTopic: soleTopic(params), total: showcase.length };
}

app/lib/return-to.mjs.source:
/**
 * The `Referer` is attacker-supplied, so it is proven same-origin before the toggle redirects to it.
 *
 * @param {Request} request
 * @returns {string}
 */
export function safeReturnTo(request) {
  const referer = request.headers.get("referer");
  if (!referer) return "/";
  try {
    const url = new URL(referer);
    if (url.origin !== new URL(request.url).origin) return "/";
    // `new URL("https://site//evil.com")` has pathname `//evil.com`, and `Location: //evil.com`
    // is protocol-relative, resolving against another HOST. The origin check does not catch it.
    if (url.pathname.startsWith("//")) return "/";
    // `Referer` never carries a fragment (RFC 9110), so `url.hash` is empty for browser requests;
    // it is echoed for callers that pass a URL from elsewhere.
    return url.pathname + url.search + url.hash;
  } catch {
    return "/";
  }
}

app/lib/search/follow-up.mjs.source:
// Not in ask-prompt.mjs: the client imports this, and importing from there shipped the system prompt
// in the client bundle (tree-shaking did not remove it), which would make answerLeaksPrompt moot.

/** A marker, not "the last line": splitting on position would eat a sentence when no follow-up came. */
export const FOLLOW_UP_MARKER = "NEXT:";

/**
 * The marker must start a line (mid-sentence it is prose), and is searched from the end, since the
 * follow-up is asked for last.
 *
 * @param {string} raw
 * @returns {{ answer: string, followUp: string | null }}
 */
export function splitFollowUp(raw) {
  const lines = raw.split("\n");
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    /* The ?? "" only satisfies noUncheckedIndexedAccess. */
    const line = (lines[i] ?? "").trim();
    if (!line.startsWith(FOLLOW_UP_MARKER)) continue;
    const question = line.slice(FOLLOW_UP_MARKER.length).trim();
    const answer = lines.slice(0, i).join("\n").trimEnd();
    return { answer, followUp: question.length > 0 ? question : null };
  }
  return { answer: raw, followUp: null };
}

app/lib/series-path.mjs.source:
/**
 * A series is FREE TEXT, unlike a tag, so it is normalized here and nowhere else; the archive
 * builds and resolves its URL through this one function so the two cannot drift.
 */

/**
 * Empty for a name with no alphanumerics; the caller decides what that means.
 *
 * @param {string} name
 * @returns {string}
 */
export function seriesSlug(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Takes the NAME, so no caller can forget to slugify and put two spellings of one URL on the site.
 *
 * @param {string} name
 * @returns {string} a site-absolute path
 */
export function seriesPath(name) {
  return `/writing/series/${encodeURIComponent(seriesSlug(name))}`;
}

app/lib/wordpress-redirects.mjs.source:
/**
 * The old WordPress site's addresses, answered on the apex host (and www) so they are live the moment
 * DNS moves: a 301 to the page that replaces each one, or 410 Gone for what was removed. The map is
 * cutover.md's "Redirect map" (Capsid, dustinedwards), decided 2026-09-27; this file is that record in
 * code, pattern rules first, then explicit rows.
 *
 * Host-scoped, because the workers.dev host serves the new site's own paths and must never see these.
 * These are the only moves the gateway answers: the new site's own old addresses do not redirect (Dustin,
 * 2026-10-20: "the only redirects should be from the old site to the new site").
 *
 * Paths match with and without the trailing slash. The query is ignored: a 301 never carries it, since
 * WordPress's `?et_blog` and `?profiletab=` mean nothing on the new site.
 */

import { PUBLICATIONS_PREFIX } from "./publications/pdf-redirect.mjs";
import { SITE_ORIGIN } from "./site-origin.mjs";

const APEX_HOSTS = new Set(["dustinedwards.info", "www.dustinedwards.info"]);

/** @param {string} hostname */
export function isApexHost(hostname) {
  return APEX_HOSTS.has(hostname.toLowerCase());
}

/**
 * Where a request to `www` goes: the apex, in ONE hop. The apex is the canonical host, so `www` serving the same
 * pages would be a second copy of every URL. An old WordPress address goes straight to the page that replaces it
 * (the map's own Location, which carries no query), so a `www` reader of an old URL is not sent through two
 * redirects. Everything else keeps its path and query. A removed address (410) goes to the apex too, which
 * answers it. Null for any host but `www`.
 *
 * @param {string} hostname
 * @param {string} pathname
 * @param {string} search the request's query string, with its `?`, or ""
 * @returns {string | null} an absolute https URL on the apex
 */
export function wwwRedirectTarget(hostname, pathname, search) {
  if (hostname.toLowerCase() !== "www.dustinedwards.info") return null;
  const disposition = wordpressDisposition(pathname);
  // The apex drops a trailing slash (canonicalRedirect), except on a paper and an old WordPress address, so it goes in
  // this same hop: `http://www/about/` is one redirect, not two.
  const path =
    disposition === null && !pathname.startsWith(PUBLICATIONS_PREFIX) ? pathname.replace(/(.)\/+$/, "$1") : pathname;
  const target = disposition?.status === 301 ? disposition.location : `${path}${search}`;
  return new URL(target, SITE_ORIGIN).toString();
}

/**
 * Not kept, and not put in R2: its protocol is rewritten as a page, so the old PDF address, which
 * still earns clicks, points there (Dustin, 2026-09-27).
 */
export const BAYLOR_PDF = "/wp-content/uploads/2017/09/DNA-Extraction-Protocol-Baylor.pdf";
const CV_PDF = "/wp-content/uploads/2019/02/Dustin-Edwards-Curriculum-Vitae-2019.pdf";

/**
 * Targets whose pages do not exist yet. Every 301 into one of these answers 404 until its page job
 * lands, so the switch checklist reads this list: it must be empty, or each entry accepted, before
 * DNS moves.
 */
export const PENDING_TARGETS = [
  "/research",
  "/research/retroviruses",
  "/research/bacteriophages",
  "/research/science-education",
  "/research/phages",
  "/research/protocols",
  "/research/protocols/phage-isolation",
  "/research/protocols/phage-dna-extraction",
  "/research/protocols/coi-primers",
  "/research/protocols/rev-lpdv-primers",
  "/research/protocols/pan-avian-gapdh",
  "/teaching",
  "/teaching/phage-discovery",
  "/teaching/virus-isolation",
  "/teaching/phage-bioinformatics",
  "/teaching/central-dogma",
  "/teaching/study-skills",
  "/research/retroviruses/avian",
];

/**
 * @typedef {{ status: 301, location: string } | { status: 410 }} Disposition
 */

/** Where every student and author profile goes, except Dustin's own. */
export const PROFILE_TARGET = "/teaching/phage-discovery#roster";

/** @type {(location: string) => Disposition} */
const moved = (location) => ({ status: 301, location });
/** @type {Disposition} */
const GONE = { status: 410 };

/**
 * Pattern rules, in order; each reads the path without its trailing slash. `null` passes to the next.
 * @type {Array<(path: string) => Disposition | null>}
 */
const PATTERNS = [
  (p) => {
    const name = /^\/(?:discovery|annotation)-of-([a-z0-9-]+)$/i.exec(p)?.[1];
    return name ? moved(`/research/phages#${name.toLowerCase()}`) : null;
  },
  (p) =>
    ["/phylogenetics-lysm", "/arlo-gene-67", "/arlo-gene-67-cloning", "/raspberry-pi-plaque-counter"].includes(p)
      ? moved("/research/phages")
      : null,
  // The lab's own directory answered "how do I join", so it goes to Join the lab, ahead of the rule below.
  (p) => (p === "/directory-research-group" ? moved("/teaching#join-the-lab") : null),
  (p) => (/^\/directory-[^/]+$/.test(p) ? moved("/teaching/phage-discovery") : null),
  // Dustin's own author page ranks for his name, so it goes to the About page, ahead of the rule below.
  (p) => (p === "/author/dustin" ? moved("/about") : null),
  // The bare /user/ was the membership directory, so it is gone with the membership pages.
  (p) => (["/user", "/register", "/members", "/logout", "/account", "/password-reset"].includes(p) ? GONE : null),
  // Every other student and author profile (146 in Search Console, 147 with Dustin's own) goes to the
  // roster at the bottom of the Phage Discovery Program page, as on the old site (Dustin, 2026-09-27).
  (p) => (/^\/(?:user|author)(?:\/.*)?$/.test(p) ? moved(PROFILE_TARGET) : null),
  (p) =>
    /^\/(?:category\/phage-isolation-notes|microbiomes\/page|phages\/page)(?:\/.*)?$/.test(p)
      ? moved("/research/phages")
      : null,
  (p) => (/^\/knowledge-base\/category(?:\/.*)?$/.test(p) ? moved("/research/protocols") : null),
  (p) => (/^\/(?:category|tag)(?:\/.*)?$/.test(p) ? GONE : null),
  (p) => (p === BAYLOR_PDF ? moved("/research/protocols/phage-dna-extraction") : null),
  (p) => (p === CV_PDF ? moved("/dustin-edwards-cv.pdf") : null),
  // Both still earn clicks or impressions: a lab protocol goes to the page that carries it.
  (p) => (p === "/wp-content/uploads/2023/11/Electrophoresis.pdf" ? moved("/research/protocols") : null),
  (p) => (p === "/wp-content/uploads/2023/11/DNA-Extraction-Scan.pdf" ? moved("/research/protocols/phage-dna-extraction") : null),
  (p) => (p.startsWith("/wp-content/uploads/") ? GONE : null),
  // Nothing on the new site does these calculations (Dustin, 2026-09-27).
  (p) => (["/molarity-calculator", "/knowledge-base/metric-prefix"].includes(p) ? GONE : null),
];

/** Explicit rows, keyed by the old path without its trailing slash. */
const ROWS = /** @type {Record<string, string>} */ ({
  // Yoast's sitemap index, which Search Console still holds from the WordPress site.
  "/sitemap_index.xml": "/sitemap.xml",
  "/knowledge-base/pcr-coi-lco1490-hco2198": "/research/protocols/coi-primers",
  // The old pages were a course and a program, so each goes to the course or program, not a protocol.
  "/virus-isolation": "/teaching/virus-isolation",
  "/phage-discovery": "/teaching/phage-discovery",
  // No Wolbachia page: it is not Dustin's research any more, so its methods land on the protocols.
  "/wolbachia-project-genetic-techniques": "/research/protocols",
  "/knowledge-base/pcr-wolbachia-16s-rrna": "/research/protocols",
  "/gentech-2018a": "/research/protocols",
  "/research": "/research",
